local function moveTo(cf)
    local rp = rootPart()
    if not rp then return end
    if (rp.Position - cf.Position).Magnitude > 4 then rp.CFrame = cf end
    rp.AssemblyLinearVelocity = Vector3.zero
    rp.AssemblyAngularVelocity = Vector3.zero
end
-- Shared noclip that REMEMBERS each part's original collision so it can be restored. Turning a farm
-- (or the manual toggle) off must never leave you phasing through mountains. Records only parts that
-- were collidable; restoreClip() puts them back and is called whenever every noclip source is off.
local collideOrig = setmetatable({}, { __mode = "k" })
-- part list cached per model (rebuilt every 2s / on respawn) -- noclip runs every frame in PvP/Boss and a
-- full GetDescendants() of a kaiju 60x a second was pure allocation churn
local clipCache = { model = nil, parts = {}, at = 0 }
local function noclipChar()
    local c = liveModel(); if not c then return end
    if clipCache.model ~= c or os.clock() > clipCache.at then
        local parts = {}
        for _, p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") then parts[#parts + 1] = p end end
        clipCache.model, clipCache.parts, clipCache.at = c, parts, os.clock() + 2
    end
    for _, p in ipairs(clipCache.parts) do
        if p.CanCollide then
            if collideOrig[p] == nil then collideOrig[p] = true end
            p.CanCollide = false
        end
    end
end
local function restoreClip()
    for p, v in pairs(collideOrig) do pcall(function() if p.Parent then p.CanCollide = v end end) end
    collideOrig = setmetatable({}, { __mode = "k" })
end
-- restore only when nothing still wants noclip (manual toggle / pvp positioning)
local function maybeRestoreClip()
    if pvpFarming then return end   -- (Auto Farm doesn't use noclip, so it must not block the restore)
    if Toggles.k_noclip and Toggles.k_noclip.Value then return end
    if Toggles.k_bossfarm and Toggles.k_bossfarm.Value then return end
    if Toggles.k_beamcycle and Toggles.k_beamcycle.Value then return end
    restoreClip()
end
-- ANTI-FLING: big kaiju (e.g. Godzilla Ultima) overlap building geometry when we hard-snap next to them,
-- and the physics solver ejects the huge model skyward. Zeroing velocity every frame while farming
-- cancels that impulse before it builds up, so you don't get launched into the sky.
track(RunService.Heartbeat:Connect(function()
    if not farming or archBusy then return end
    local rp = rootPart()
    if rp then rp.AssemblyLinearVelocity = Vector3.zero; rp.AssemblyAngularVelocity = Vector3.zero end
end))

-- STICKY SELECTIONS: Obsidian throws away a saved dropdown value that isn't in its list yet, and the
-- building-type / player lists are only filled in after the config loads -- so those picks never came
-- back. We remember them in our own file and re-apply whatever is available every time a list refreshes
-- (a picked player who isn't in this server stays remembered for later).
local STK = { busy = false, want = {}, file = "KaijuAlpha/cw_sticky.json" }
pcall(function()
    if isfile and isfile(STK.file) then
        local d = HttpService:JSONDecode(readfile(STK.file))
        if type(d) == "table" then STK.want = d end
    end
end)
function STK.save()
    pcall(function()
        if makefolder and isfolder and not isfolder("KaijuAlpha") then makefolder("KaijuAlpha") end
        writefile(STK.file, HttpService:JSONEncode(STK.want))
    end)
end
function STK.set(list) local s = {}; for _, v in ipairs(list or {}) do s[v] = true end; return s end
function STK.track(id)
    local o = Opt[id]
    if not o then return end
    o:OnChanged(function()
        if STK.busy then return end
        local v = o.Value
        if type(v) == "table" then
            local inList, keep = STK.set(o.Values), {}
            local old = STK.want[id]
            for name in pairs(type(old) == "table" and old or {}) do
                if not inList[name] then keep[name] = true end   -- remembered but not available right now
            end
            for name, on in pairs(v) do if on then keep[name] = true end end
            STK.want[id] = keep
        else
            STK.want[id] = (v ~= nil and v ~= "") and v or nil
        end
        STK.save()
    end)
end
function STK.setValues(id, list)
    local o = Opt[id]
    if not o then return end
    STK.busy = true
    pcall(function() o:SetValues(list) end)
    local w = STK.want[id]
    if w ~= nil then
        local inList = STK.set(list)
        if type(w) == "table" then
            local sel = {}
            for name in pairs(w) do if inList[name] then sel[name] = true end end
            pcall(function() o:SetValue(sel) end)
        elseif inList[w] then
            pcall(function() o:SetValue(w) end)
        end
    end
    STK.busy = false
end

