FarmBox:AddSlider("k_farmdelay", { Text = "Farm Delay", Default = 0.1, Min = 0.05, Max = 1, Rounding = 2, Suffix = " s", Tooltip = "Raise this if the farm lags/crashes you (heavy kaiju like Jet Jaguar). Higher = slower but safer." })
local lastScanKaiju, lastScanIsland
task.spawn(function()
    while RUNNING do
        task.wait(2)
        if isSpawned() then
            local k = currentKaiju()
            if k ~= lastScanKaiju then
                local names = discoverSkills()
                if #names > 0 then
                    lastScanKaiju = k
                    local prev = {}
                    local v = Opt.k_skills and Opt.k_skills.Value
                    if type(v) == "table" then
                        for kk, val in pairs(v) do
                            if val == true then prev[kk] = true elseif type(val) == "string" then prev[val] = true end
                        end
                    end
                    pcall(function() Opt.k_skills:SetValues(names) end)
                    local keep = {}
                    for _, n in ipairs(names) do if prev[n] then keep[n] = true end end
                    if next(keep) then pcall(function() Opt.k_skills:SetValue(keep) end) end
                    -- mirror onto the PvP attacks dropdown, preserving its own selection
                    if Opt.k_pvp_skills then
                        local pprev = {}
                        local pv = Opt.k_pvp_skills.Value
                        if type(pv) == "table" then
                            for kk, val in pairs(pv) do
                                if val == true then pprev[kk] = true elseif type(val) == "string" then pprev[val] = true end
                            end
                        end
                        pcall(function() Opt.k_pvp_skills:SetValues(names) end)
                        local pkeep = {}
                        for _, n in ipairs(names) do if pprev[n] then pkeep[n] = true end end
                        if next(pkeep) then pcall(function() Opt.k_pvp_skills:SetValue(pkeep) end) end
                    end
                end
            end
            local isl = Opt.k_island and Opt.k_island.Value
            if isl ~= lastScanIsland then
                local list = discoverTypes()
                if #list > 0 then
                    lastScanIsland = isl
                    suppressTypesCb = true
                    if type(STK.want.k_types) == "table" and next(STK.want.k_types) then typesUserSet = true end
                    STK.setValues("k_types", list)   -- re-applies your saved building picks
                    if not typesUserSet then          -- default = every building selected, unless you changed it
                        local sel = {}; for _, t in ipairs(list) do sel[t] = true end
                        STK.busy = true
                        pcall(function() Opt.k_types:SetValue(sel) end)
                        STK.busy = false
                    end
                    suppressTypesCb = false
                end
            end
        end
    end
end)

FarmBox:AddToggle("k_farm", {
    Text = "Auto Farm", Default = false,
    Callback = function(on)
        farming = on
        if on and Toggles.k_pvp and Toggles.k_pvp.Value then Toggles.k_pvp:SetValue(false) end
        if on and Toggles.k_autopark and Toggles.k_autopark.Value then Toggles.k_autopark:SetValue(false) end
        if on and Toggles.k_beamcycle and Toggles.k_beamcycle.Value then Toggles.k_beamcycle:SetValue(false) end
        if on and Toggles.k_bossfarm and Toggles.k_bossfarm.Value then Toggles.k_bossfarm:SetValue(false) end
        if on then sessionStart() else sessionPause() end
        notify(on and "Auto Farm on" or "Auto Farm off")
        if not on then maybeRestoreClip(); return end
        task.spawn(function()
            while farming do
                if not isSpawned() then
                    if Toggles.k_respawn.Value then
                        if not ensureRespawn(Opt.k_island.Value) then task.wait(0.5) end
                    else task.wait(1) end
                else
                    local blds = getBuildings()
                    if #blds == 0 then task.wait(0.5) end   -- island cleared / not streamed yet: yield so we never tight-spin (freeze)
                    for _, b in ipairs(blds) do
                        if not farming or not isSpawned() then break end
                        if archBusy then task.wait(0.2) end   -- pause while an archetype is being taken (don't fight the TP)
                        local t0 = os.clock()
                        while farming and isSpawned() and not destroyed(b.m) and os.clock() - t0 < 20 do
                            -- the Auto Beam sweep moves you itself while a beam is active: don't tug-of-war it
                            local sweeping = beamActive and Toggles.k_autobeam and Toggles.k_autobeam.Value
                            if not archBusy and not sweeping then moveTo(cframeFor(b)) end   -- recompute each tick so Attack Distance applies LIVE; hold off while taking an archetype
                            if not sweeping then fireReadySkill() end
                            task.wait((Opt.k_farmdelay and Opt.k_farmdelay.Value) or 0.1)
                        end
                        -- after a kill, hop 300 studs straight up so the despawn/physics glitch can't
                        -- clip us through the map before we drop onto the next building
                        if destroyed(b.m) and isSpawned() then
                            local rp = rootPart()
                            if rp then
                                rp.CFrame = rp.CFrame + Vector3.new(0, 300, 0)
                                rp.AssemblyLinearVelocity = Vector3.zero
                            end
                            task.wait(0.05)
                        end
                    end
                end
            end
        end)
    end,
})

FarmBox:AddToggle("k_respawn", { Text = "Auto Respawn", Default = false, Tooltip = "Off = never auto-respawns you (leveling up / manual actions won't yank you back)" })
FarmBox:AddToggle("k_autofix", { Text = "Smart Energy", Default = false, Tooltip = "Skips attacks you can't afford so energy regenerates instead of being wasted on a dead cast. Per-kaiju costs are read from the game, so it adapts to every kaiju." })
FarmBox:AddToggle("k_autobeam", { Text = "Auto Beam", Default = false })
FarmBox:AddToggle("k_energyreset", { Text = "Auto Reset At Energy %", Default = false, Tooltip = "Respawns you the moment your energy bar drops below the % below, so it refills. Works on any kaiju, and respawns even if Auto Respawn is off." })
FarmBox:AddSlider("k_energyfix", { Text = "Reset At Energy %", Default = 20, Min = 5, Max = 60, Rounding = 0, Tooltip = "Auto Reset respawns you when your energy is at or below this % of max." })
FarmBox:AddDropdown("k_stat", { Values = { "Energy", "Strength", "Health", "Regen", "Speed" }, Default = "Energy", Text = "Auto Stat" })
FarmBox:AddToggle("k_autostat", { Text = "Auto Stats", Default = false, Tooltip = "Pours each skill point you earn into the chosen stat. Energy = fewer respawns / less crashing." })
-- The stat point buttons are named "Increase"/"Decrease" (capture-confirmed) -- there is NO "Max"
-- button, so the game only accepts those two. To dump points we fire "Increase" once per point.
-- Read the real add-button name live (matched by name, since the buttons use icons not text).
local function statAddButton(stat)
    local pg = lp:FindFirstChild("PlayerGui")
    local si = pg and pg:FindFirstChild("StatsInfo", true)
    local frame = si and si:FindFirstChild(stat)
    local point = frame and frame:FindFirstChild("Point")
    if not point then return nil end
    for _, d in ipairs(point:GetChildren()) do
        if d:IsA("TextButton") or d:IsA("ImageButton") then
            local nm = d.Name:lower()
            local txt = d:IsA("TextButton") and d.Text or ""
            if nm:find("inc") or nm:find("add") or nm:find("plus") or txt:find("+", 1, true) then
                return "Increase"   -- real Menu.lua: the 4th arg is the action "Increase"/"Decrease", not the button's name
            end
        end
    end
    return nil
end
task.spawn(function()
    while RUNNING do
        if Toggles.k_autostat and Toggles.k_autostat.Value then
            local kaiju = currentKaiju()
            -- only fire when there are skill points to actually spend (verifiable + no useless spam)
            local d = dataFolder()
            local inv = d and d:FindFirstChild("KaijuInventory")
            local kj = inv and inv:FindFirstChild(kaiju)
            local stats = kj and kj:FindFirstChild("Stats")
            local sp = stats and stats:FindFirstChild("Skill_Points")
            local pts = sp and tonumber(sp.Value) or 0
            if pts > 0 then
                local stat = (Opt.k_stat and Opt.k_stat.Value) or "Energy"
                local btn = statAddButton(stat) or "Increase"
                for _ = 1, math.min(pts, 100) do   -- "Increase" adds one point; fire once per point
                    if not (Toggles.k_autostat and Toggles.k_autostat.Value) then break end
                    pcall(function() FireServer:FireServer("UpdateStat", kaiju, stat, btn) end)
                    task.wait(0.05)
                end
            end
        end
        task.wait(1)
    end
end)
-- AUTO RESET AT ENERGY %: the instant the energy bar drops to/below the chosen % of max, respawn to
-- refill it. Standalone (NOT gated behind Smart Energy or Auto Respawn anymore -- that was the bug:
-- with Smart Energy off it never fired). Reads the same value the HUD shows (attribute, HUD-text
-- fallback). ensureRespawn does the full suicide+respawn so it works even with Auto Respawn off. A 5s
-- cooldown stops it re-firing during the respawn transition.
local energyResetAt = 0
task.spawn(function()
    while RUNNING do
        task.wait(0.4)
        if Toggles.k_energyreset and Toggles.k_energyreset.Value and isSpawned() and not respawning then
            local e, m = getEnergy()
            local thr = ((Opt.k_energyfix and Opt.k_energyfix.Value) or 20) / 100
            if e and m and m > 0 and (e / m) <= thr and os.clock() - energyResetAt > 5 then
                energyResetAt = os.clock()
                notify("Energy low (" .. math.floor(e) .. "/" .. math.floor(m) .. ") -> respawning to refill")
                ensureRespawn((Opt.k_island and Opt.k_island.Value) or "Tokyo")
            end
        end
    end
end)

-- AUTO TAKE ARCHETYPE: the Archetype pickup (need 10 to unlock Godzilla Ultima) is a ProximityPrompt
-- with a ~10s hold that spawns ~every 30 min, mostly on Isla de Mara. It only streams in when you're
-- on that island. We watch for it and fire the prompt (bypasses the 10s hold + distance), TP'ing to it
-- and back so farming isn't disturbed. Scoped in a do-block for the 200-local limit.
FarmBox:AddToggle("k_autoarch", { Text = "Auto Take Archetype", Default = false, Tooltip = "Auto-collects the Archetype pickup the instant it appears near you (spawns ~every 30 min, mostly Isla de Mara -- farm that island to catch it). Grabs it through the 10s hold." })
do
    local fireprompt = fireproximityprompt or (getgenv and getgenv().fireproximityprompt)
    local VIM = game:GetService("VirtualInputManager")
    local archTaken = setmetatable({}, { __mode = "k" })
    local function isArchPrompt(d)
        if not d:IsA("ProximityPrompt") then return false end
        local ot = tostring(d.ObjectText or ""):lower()
        return ot:find("archetype") ~= nil
    end
    local function takeArch(prompt)
        if archTaken[prompt] or not prompt.Parent then return end
        archTaken[prompt] = true
        archBusy = true
        local part = prompt.Parent
        local rp = rootPart()
        local back = rp and rp.CFrame
        if rp and part and part:IsA("BasePart") then
            pcall(function() rp.CFrame = part.CFrame + Vector3.new(0, 6, 0); rp.AssemblyLinearVelocity = Vector3.zero end)
            task.wait(0.25)
        end
        if fireprompt then
            pcall(fireprompt, prompt)
        else   -- fallback: physically hold the prompt key for its full duration
            local key = prompt.KeyboardKeyCode
            pcall(function() VIM:SendKeyEvent(true, key, false, game) end)
            task.wait((prompt.HoldDuration or 10) + 0.4)
            pcall(function() VIM:SendKeyEvent(false, key, false, game) end)
        end
        task.wait(0.3)
        notify("Took Archetype")
        if back and rootPart() then pcall(function() rootPart().CFrame = back end) end   -- return to farm spot
        archBusy = false
    end
    local function archWant()   -- take archetype if either the toggle OR auto-park is on
        return (Toggles.k_autoarch and Toggles.k_autoarch.Value) or (Toggles.k_autopark and Toggles.k_autopark.Value)
    end
    -- keep a weak set of every prompt (one scan at load + DescendantAdded) instead of re-walking the whole
    -- Workspace every 4s (that was a periodic hitch during long Auto Park sessions)
    local promptSet = setmetatable({}, { __mode = "k" })
    for _, d in ipairs(Workspace:GetDescendants()) do if d:IsA("ProximityPrompt") then promptSet[d] = true end end
    track(Workspace.DescendantAdded:Connect(function(d)
        if not d:IsA("ProximityPrompt") then return end
        promptSet[d] = true
        if archWant() and isSpawned() and isArchPrompt(d) then
            task.wait(0.3)
            takeArch(d)
        end
    end))
    task.spawn(function()   -- backup pass for one already present when you arrive
        while RUNNING do
            if archWant() and isSpawned() then
                for d in pairs(promptSet) do
                    if d.Parent and isArchPrompt(d) and not archTaken[d] then takeArch(d); break end
                end
            end
            task.wait(4)
        end
    end)
end

-- AUTO PARK (Isla de Mara): travel to Isla de Mara and rotate/hover the 3 confirmed city districts
-- (capture-derived) so the whole island stays streamed in and the archetype watcher above grabs the
-- pickup wherever it spawns (~every 30 min). Turning this on also enables taking (see archWant).
FarmBox:AddToggle("k_autopark", { Text = "Auto Park (Isla Archetype)", Default = false,
    Tooltip = "Flies to Isla de Mara and rotates its 3 cities, holding each so the Archetype streams in and gets auto-taken. Also enables Auto Take Archetype.",
    Callback = function(on)
        if on then   -- can't park + farm/pvp at once (they fight over your position)
            if Toggles.k_farm and Toggles.k_farm.Value then Toggles.k_farm:SetValue(false) end
            if Toggles.k_pvp and Toggles.k_pvp.Value then Toggles.k_pvp:SetValue(false) end
            if Toggles.k_bossfarm and Toggles.k_bossfarm.Value then Toggles.k_bossfarm:SetValue(false) end
        end
    end })
do
    local ISLA_CITIES = {
        Vector3.new(744.9, 49.1, -996.6),
        Vector3.new(1180.0, 49.1, -876.2),
        Vector3.new(963.6, 46.6, -729.5),
    }
    local HOVER = 150   -- studs above the city center, above the skyscrapers
    local HOLD = 12     -- seconds parked at each city before rotating
    local parkCF = nil  -- current hover target; the Heartbeat below holds it every frame (no jitter)
    -- per-frame hold = perfectly steady hover (the old 0.3s re-TP let gravity bob you up/down)
    track(RunService.Heartbeat:Connect(function()
        if parkCF and not archBusy and Toggles.k_autopark and Toggles.k_autopark.Value and isSpawned() then
            local rp = rootPart()
            if rp then
                rp.CFrame = parkCF
                rp.AssemblyLinearVelocity = Vector3.zero
                rp.AssemblyAngularVelocity = Vector3.zero
            end
        end
    end))
    task.spawn(function()
        local idx = 1
        while RUNNING do
            if Toggles.k_autopark and Toggles.k_autopark.Value and isSpawned() then
                parkCF = CFrame.new(ISLA_CITIES[idx] + Vector3.new(0, HOVER, 0))
                local t0 = os.clock()
                while Toggles.k_autopark and Toggles.k_autopark.Value and isSpawned() and os.clock() - t0 < HOLD do task.wait(0.5) end
                idx = idx % #ISLA_CITIES + 1
            else
                parkCF = nil
                task.wait(1)
            end
        end
    end)
end

-- ITEM ESP: highlight world pickups (Archetype, Monster Zero Skull, etc.) -- they're ProximityPrompts
-- with a name (ObjectText). We highlight the pickup part + label it with name + distance. Only shows
-- pickups streamed in near you. Scoped in a do-block for the 200-local limit.
FarmBox:AddToggle("k_item_esp", { Text = "Item ESP", Default = false, Tooltip = "Highlights item pickups (Archetype, etc.) with name + distance and pings you when one loads. Items only load when you're near them (e.g. farm Isla de Mara for Archetype)." })
do
    -- real-source dump (2026-10-01): no client script handles pickups and the world has NO other prompts,
    -- so every ProximityPrompt is a server-spawned pickup. Show them all (name = ObjectText, else
    -- ActionText, else the model name), announce new ones, and count what's loaded so users can tell
    -- "nothing nearby" (streaming) apart from "broken".
    local lblItems = FarmBox:AddLabel("Items loaded: 0", true)
    local prompts = setmetatable({}, { __mode = "k" })
    local announced = setmetatable({}, { __mode = "k" })
    local function promptName(prompt)
        local ot = tostring(prompt.ObjectText or "")
        if ot ~= "" then return ot end
        local at = tostring(prompt.ActionText or "")
        local par = prompt.Parent
        local m = par and (par:IsA("Model") and par or par:FindFirstAncestorWhichIsA("Model"))
        local nm = (m and m ~= Workspace and m.Name) or (par and par.Name) or "Item"
        return (at ~= "" and at ~= "Interact") and (nm .. " (" .. at .. ")") or nm
    end
    local function addPrompt(d) if d:IsA("ProximityPrompt") then prompts[d] = true end end
    for _, d in ipairs(Workspace:GetDescendants()) do addPrompt(d) end
    track(Workspace.DescendantAdded:Connect(addPrompt))
    local function adornPart(prompt)
        local p = prompt.Parent
        if not p then return nil end
        if p:IsA("BasePart") then return p end
        if p:IsA("Attachment") then return (p.Parent and p.Parent:IsA("BasePart")) and p.Parent or nil end
        if p:IsA("Model") then return p.PrimaryPart or p:FindFirstChildWhichIsA("BasePart") end
        return nil
    end
    local cache = {}
    local function clr(x) pcall(function() x.hl:Destroy() end); pcall(function() x.bb:Destroy() end) end
    local function make(part)
        local hl = Instance.new("Highlight")
        hl.FillColor = Color3.fromRGB(255, 215, 0); hl.OutlineColor = Color3.fromRGB(255, 255, 255)
        hl.FillTransparency = 0.4; hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop; hl.Adornee = part; hl.Parent = part
        local bb = Instance.new("BillboardGui")
        bb.Size = UDim2.fromOffset(230, 34); bb.StudsOffset = Vector3.new(0, 5, 0); bb.AlwaysOnTop = true
        bb.MaxDistance = 100000; bb.Adornee = part; bb.Parent = part
        local tl = Instance.new("TextLabel")
        tl.Size = UDim2.fromScale(1, 1); tl.BackgroundTransparency = 1; tl.TextColor3 = Color3.fromRGB(255, 235, 120)
        tl.TextStrokeTransparency = 0.3; tl.Font = Enum.Font.GothamBold; tl.TextSize = 13; tl.Parent = bb
        return { hl = hl, bb = bb, tl = tl }
    end
    task.spawn(function()
        while RUNNING do
            pcall(function()
                if Toggles.k_item_esp and Toggles.k_item_esp.Value then
                    local me = rootPart(); local myPos = me and me.Position
                    local present = {}
                    local count = 0
                    for prompt in pairs(prompts) do
                        local part = prompt.Parent and adornPart(prompt) or nil
                        local ot = part and promptName(prompt) or ""
                        if part then
                            present[prompt] = true
                            count = count + 1
                            if not announced[prompt] then
                                announced[prompt] = true
                                local d = myPos and math.floor((part.Position - myPos).Magnitude) or 0
                                notify(("Item: %s  (%d studs)"):format(ot, d))
                            end
                            local x = cache[prompt]
                            if not x or not (x.hl and x.hl.Parent and x.bb and x.bb.Parent) then
                                if x then clr(x) end
                                local ok, made = pcall(make, part)
                                if ok then x = made; cache[prompt] = made else x = nil; cache[prompt] = nil end
                            end
                            if x then
                                local dist = myPos and math.floor((part.Position - myPos).Magnitude) or 0
                                pcall(function() x.tl.Text = ot .. "  |  " .. dist .. " studs" end)
                            end
                        end
                    end
                    for p, x in pairs(cache) do if not present[p] then clr(x); cache[p] = nil end end
                    lblItems:SetText(count > 0 and ("Items loaded: %d"):format(count) or "Items loaded: 0  (none near you -- they only load close by)")
                elseif next(cache) then
                    for p, x in pairs(cache) do clr(x); cache[p] = nil end
                    lblItems:SetText("Items loaded: -")
                end
            end)
            task.wait(0.5)
        end
    end)
    onClean(function() for p, x in pairs(cache) do clr(x) end; cache = {} end)
end

task.spawn(function()
    while RUNNING do
        if Toggles.k_autobeam and Toggles.k_autobeam.Value and farming and beamActive and isSpawned() and not archBusy then
            local swept = 0
            for _, b in ipairs(getBuildings()) do
                if not (Toggles.k_autobeam.Value and farming and beamActive and isSpawned()) or archBusy then break end
                if not destroyed(b.m) then
                    moveTo(cframeFor(b))
                    BEAMCTL.pos = b.p   -- steer the game's own per-frame beam point at this building
                    pcall(function() BeamRemote:FireServer(b.p) end)
                    swept = swept + 1
                    if swept >= 20 then break end
                    task.wait(0.15)
                end
            end
            BEAMCTL.pos = nil
            task.wait(0.25)
        else
            task.wait(0.15)
        end
    end
end)

-- ============================================================================
-- PVP FARM (own tab). Damage is 100% server-authoritative: UseSkill sends only the skill NAME; the server
-- builds the hitbox from KaijuData at YOUR HRP*Offset and hits whoever is inside. No target/backstab logic
-- exists server-side, so "where" you stand is cosmetic for damage -- it only affects jitter/visuals. What
-- matters is: face the target, be close, same Y. We track the target PER FRAME (smooth) and spam skills.
-- ============================================================================
local pvpKills = 0
local pvpTargetName = "-"
local pvpHop   -- assigned later (needs httpGet, defined further down): hop to a different populated server
local function enemyList()
    local live = Workspace:FindFirstChild("Live")
    local out = {}
    if not live then return out end
    for _, m in ipairs(live:GetChildren()) do
        if m:IsA("Model") and m.Name ~= lp.Name and Players:FindFirstChild(m.Name) then   -- real players only, not NPCs
            local h = m:FindFirstChildWhichIsA("Humanoid")
            local rp = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart")
            if h and rp then out[#out + 1] = { m = m, rp = rp, h = h, name = m.Name, kaiju = m:GetAttribute("KaijuName") or "?" } end
        end
    end
    return out
end
local function enemyAlive(e)
    return e and e.m and e.m.Parent and e.rp and e.rp.Parent and e.h and e.h.Health > 0
end
-- Spawn protection (capture-confirmed): a fresh spawn carries attribute Spawning=true plus a Highlight
-- named "Protect" (the body overlay), which both clear when protection ends. We wait until they're gone.
-- NOTE: we deliberately do NOT gate on the IFrame attribute -- it also flags brief combat dodge i-frames,
-- which would make PvP stutter/re-target every time the enemy dodges. Spawning + Protect are spawn-specific.
local function shielded(e)
    local m = e and e.m
    if not m then return false end
    if m:GetAttribute("Spawning") == true then return true end
    local p = m:FindFirstChild("Protect")
    if p and p:IsA("Highlight") then return true end
    if m:FindFirstChildOfClass("ForceField") then return true end   -- fallback, just in case
    return false
end
-- WHITELIST ("Avoid All Except"): only players picked in "Engage Only" are attacked; everyone else --
-- including anyone who joins later -- is avoided automatically. Empty = attack everyone (normal farm).
local function onlySet()
    local dd = Opt.k_pvp_only; local v = dd and dd.Value
    if type(v) ~= "table" then return nil end
    local set, any = {}, false
    for k, val in pairs(v) do
        if val == true then set[k:lower()] = true; any = true
        elseif type(val) == "string" then set[val:lower()] = true; any = true end
    end
    return any and set or nil
end
-- optional kaiju filter (empty = any kaiju)
local function kaijuFilter()
    local dd = Opt.k_pvp_kaiju; local v = dd and dd.Value
    if type(v) ~= "table" then return nil end
    local set, any = {}, false
    for k, val in pairs(v) do
        if val == true then set[k] = true; any = true elseif type(val) == "string" then set[val] = true; any = true end
    end
    return any and set or nil
end
local function allKaiju()
    local out = {}
    local kd = RS:FindFirstChild("Shared") and RS.Shared:FindFirstChild("KaijuData")
    if kd then for _, c in ipairs(kd:GetChildren()) do out[#out + 1] = c.Name end end
    table.sort(out)
    return out
end

local function pickEnemy()
    local kf, only = kaijuFilter(), onlySet()
    local elig = {}
    for _, e in ipairs(enemyList()) do
        if e.h.Health > 0 and (not kf or kf[e.kaiju]) and (not only or only[e.name:lower()]) then
            e.shield = shielded(e)
            elig[#elig + 1] = e
        end
    end
    if #elig == 0 then return nil end
    local mode = (Opt.k_pvp_mode and Opt.k_pvp_mode.Value) or "Nearest"
    local me = rootPart()
    local function choose(subset)
        if #subset == 0 then return nil end
        if mode == "Specific" then
            local want = Opt.k_pvp_target and Opt.k_pvp_target.Value
            for _, e in ipairs(subset) do if e.name == want then return e end end
            return nil
        elseif mode == "Lowest Health" then
            local best, bestH
            for _, e in ipairs(subset) do if not bestH or e.h.Health < bestH then best, bestH = e, e.h.Health end end
            return best
        elseif mode == "Random" then
            return subset[math.random(1, #subset)]
        else -- Nearest
            if not me then return subset[1] end
            local best, bestD
            for _, e in ipairs(subset) do
                local d = (e.rp.Position - me.Position).Magnitude
                if not bestD or d < bestD then best, bestD = e, d end
            end
            return best
        end
    end
    -- prefer targets whose forcefield is already off; otherwise camp the best shielded one so we
    -- re-engage the instant their forcefield drops (re-kill on freshly-respawned players).
    local open, shut = {}, {}
    for _, e in ipairs(elig) do if e.shield then shut[#shut + 1] = e else open[#open + 1] = e end end
    return choose(open) or choose(shut)
end

-- where to sit relative to the target (all modes FACE the target)
local function standCFrame(e)
    local pos = e.rp.Position
    local ecf = e.rp.CFrame
    local dist = (Opt.k_pvp_dist and Opt.k_pvp_dist.Value) or 4
    local mode = (Opt.k_pvp_pos and Opt.k_pvp_pos.Value) or "Front"
    local sp
    if mode == "Back" then sp = pos - ecf.LookVector * dist          -- behind their facing
    elseif mode == "Side" then sp = pos + ecf.RightVector * dist       -- to their right
    elseif mode == "Above" then sp = pos + Vector3.new(0, math.max(dist, 8), 0)
    else sp = pos + ecf.LookVector * dist end                          -- Front (in front of them)
    if mode ~= "Above" then sp = Vector3.new(sp.X, pos.Y, sp.Z) end    -- match Y so the box covers them
    return CFrame.lookAt(sp, pos)
end
local function pvpMove(cf)
    local rp = rootPart(); if not rp then return end
    rp.CFrame = cf
    rp.AssemblyLinearVelocity = Vector3.zero
    rp.AssemblyAngularVelocity = Vector3.zero
end
local function pvpNoclip() noclipChar() end   -- shared noclip that can be restored on PvP off

local pvpCurrent = nil
local pvpHideCF = nil   -- underground hide spot after a kill; pinned so gravity+noclip don't sink us to the void
-- per-frame positioning = smooth tracking (no 10Hz jitter); skill spam stays on the loop below.
-- Noclip stays on for the WHOLE time PvP farm is on (not just while locked on a target) so the
-- post-kill "hide underground" position holds instead of the character being ejected by collision.
track(RunService.Heartbeat:Connect(function()
    if not (pvpFarming and isSpawned()) then return end
    pvpNoclip()
    if archBusy then return end   -- taking an archetype -> let takeArch control position, don't fight it
    if enemyAlive(pvpCurrent) then
        pvpMove(standCFrame(pvpCurrent))
    elseif pvpHideCF then
        pvpMove(pvpHideCF)   -- pin underground so we don't fall through the world to -500 and die
    end
end))

