local PvpBox = PvpTab:AddRightGroupbox("Actions")
PvpBox:AddToggle("k_pvp", {
    Text = "Farm Players", Default = false,
    Callback = function(on)
        pvpFarming = on
        if on and Toggles.k_farm and Toggles.k_farm.Value then Toggles.k_farm:SetValue(false) end
        if on and Toggles.k_autopark and Toggles.k_autopark.Value then Toggles.k_autopark:SetValue(false) end
        if on and Toggles.k_beamcycle and Toggles.k_beamcycle.Value then Toggles.k_beamcycle:SetValue(false) end
        if on and Toggles.k_bossfarm and Toggles.k_bossfarm.Value then Toggles.k_bossfarm:SetValue(false) end
        if on then sessionStart() else sessionPause() end
        notify(on and "PvP farm on" or "PvP farm off")
        if not on then
            pvpCurrent = nil; pvpTargetName = "-"
            if pvpHideCF then   -- we were hiding underground -> lift back above the surface BEFORE going
                local rp = rootPart()   -- solid, otherwise you'd be stuck inside terrain (the noclip glitch)
                if rp then pcall(function() rp.CFrame = pvpHideCF + Vector3.new(0, 200, 0); rp.AssemblyLinearVelocity = Vector3.zero end) end
                pvpHideCF = nil
                task.wait(0.1)
            end
            maybeRestoreClip()
            return
        end
        task.spawn(function()
            while pvpFarming do
                if not isSpawned() then
                    pvpCurrent = nil; pvpTargetName = "-"; pvpHideCF = nil
                    if Toggles.k_respawn.Value then
                        if not ensureRespawn(Opt.k_island.Value) then task.wait(0.5) end
                    else task.wait(1) end
                else
                    local e = pickEnemy()
                    if not e then
                        pvpCurrent = nil; pvpTargetName = "-"; task.wait(0.5)
                    else
                        pvpCurrent = e; pvpTargetName = e.name; pvpHideCF = nil   -- engaging -> stop hiding
                        -- FORCEFIELD-OFF RE-KILL: if the target is still shielded (just respawned/invuln),
                        -- sit on them (Heartbeat positions us) and hold fire until the forcefield drops,
                        -- then engage the exact moment they're vulnerable.
                        local shieldT0 = os.clock()
                        while pvpFarming and isSpawned() and enemyAlive(e) and shielded(e) and os.clock() - shieldT0 < 10 do   -- 10s cap: AFK-in-spawn targets can't stall PvP forever
                            local ol = onlySet()
                            if ol and not ol[e.name:lower()] then break end
                            task.wait(0.1)
                        end
                        local lastHp = e.h.Health
                        local stall = os.clock()
                        while pvpFarming and isSpawned() and enemyAlive(e) and not shielded(e) do
                            local ol = onlySet()
                            if ol and not ol[e.name:lower()] then break end   -- removed from whitelist mid-fight -> drop
                            fireReadySkill("k_pvp_skills")        -- positioning handled per-frame on Heartbeat
                            local hp = e.h.Health
                            if hp < lastHp - 0.5 then lastHp = hp; stall = os.clock() end   -- still damaging -> stay
                            if os.clock() - stall > 8 then break end   -- no damage 8s (fled/unreachable) -> switch
                            task.wait(0.1)
                        end
                        local killed = e.h and e.h.Health <= 0
                        if killed then pvpKills = pvpKills + 1 end   -- target went down while locked
                        pvpCurrent = nil
                        -- after a kill, drop 100 studs underground to hide (noclip stays on while PvP
                        -- farm is on, so you sit there safely until the next target is picked)
                        if killed and isSpawned() then
                            local rp = rootPart()
                            if rp then
                                local under = rp.CFrame - Vector3.new(0, 100, 0)
                                rp.CFrame = under
                                rp.AssemblyLinearVelocity = Vector3.zero
                                pvpHideCF = under   -- Heartbeat pins us here until the next target
                            end
                            task.wait(0.1)
                        end
                        -- kill X players -> hop to a fresh populated server
                        if Toggles.k_pvp_hop and Toggles.k_pvp_hop.Value and pvpHop then
                            local need = (Opt.k_pvp_hopn and Opt.k_pvp_hopn.Value) or 5
                            if pvpKills >= need then
                                notify("Hopping after " .. pvpKills .. " downs")
                                pvpKills = 0
                                pvpHop()
                                task.wait(3)
                            end
                        end
                    end
                end
            end
        end)
    end,
})
