end)

-- Player ESP (name + health + distance), colored by remaining health
local pespCache = {}
local function clearPEsp(x) pcall(function() x.hl:Destroy() end); pcall(function() x.bb:Destroy() end) end
local function hpColor(frac)
    frac = math.clamp(frac or 1, 0, 1)
    return Color3.fromRGB(math.floor(255 * (1 - frac)), math.floor(200 * frac), 40)
end
local function makePEsp(m)
    local hl = Instance.new("Highlight")
    hl.FillColor = Color3.fromRGB(255, 60, 60); hl.OutlineColor = Color3.fromRGB(255, 255, 255)
    hl.FillTransparency = 0.65; hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop; hl.Adornee = m; hl.Parent = m
    local bb = Instance.new("BillboardGui")
    bb.Size = UDim2.fromOffset(210, 40); bb.StudsOffset = Vector3.new(0, 6, 0); bb.AlwaysOnTop = true
    bb.MaxDistance = 100000   -- show the label at any distance the model is still streamed in
    bb.Adornee = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart") or m:FindFirstChildWhichIsA("BasePart"); bb.Parent = m
    local tl = Instance.new("TextLabel")
    tl.Size = UDim2.fromScale(1, 1); tl.BackgroundTransparency = 1; tl.TextColor3 = Color3.fromRGB(255, 255, 255)
    tl.TextStrokeTransparency = 0.3; tl.Font = Enum.Font.GothamBold; tl.TextSize = 13; tl.Parent = bb
    return { hl = hl, bb = bb, tl = tl }
end
task.spawn(function()
    while RUNNING do
        -- entire tick is pcall'd so a model destroyed mid-read (death / streaming out) can never kill
        -- the loop -- that was the "ESP glitches, gotta reset it" bug.
        pcall(function()
            if Toggles.k_pvp_esp and Toggles.k_pvp_esp.Value then
                local me = rootPart(); local myPos = me and me.Position
                local present = {}
                local maxD = (Opt.k_esp_dist and Opt.k_esp_dist.Value) or 5000
                for _, e in ipairs(enemyList()) do
                    if e.h and e.h.Parent and e.h.Health > 0 and e.rp and e.rp.Parent then
                        local dist = myPos and math.floor((e.rp.Position - myPos).Magnitude) or 0
                        if dist <= maxD then   -- ESP Distance limit -> beyond this, no ESP (and it gets cleared below)
                            present[e.m] = true
                            local x = pespCache[e.m]
                            if not x or not (x.hl and x.hl.Parent and x.bb and x.bb.Parent) then   -- recreate if either piece was culled
                                if x then clearPEsp(x) end
                                local ok, made = pcall(makePEsp, e.m)
                                if ok and made then x = made; pespCache[e.m] = made else x = nil; pespCache[e.m] = nil end
                            end
                            if x then
                                local frac = (e.h.MaxHealth > 0) and (e.h.Health / e.h.MaxHealth) or 1
                                pcall(function()
                                    x.tl.Text = string.format("%s  [%s]\nHP %d  |  %d studs", e.name, e.kaiju or "?", math.floor(e.h.Health), dist)
                                    x.tl.TextColor3 = hpColor(frac)
                                    x.hl.FillColor = hpColor(frac)
                                end)
                            end
                        end
                    end
                end
                for m, x in pairs(pespCache) do if not present[m] then clearPEsp(x); pespCache[m] = nil end end
            elseif next(pespCache) then
                for m, x in pairs(pespCache) do clearPEsp(x); pespCache[m] = nil end
            end
        end)
        task.wait(0.4)
    end
end)
-- destroy any ESP highlights/labels on unload or re-exec (they're parented to player models, not the GUI)
onClean(function() for m, x in pairs(pespCache) do clearPEsp(x) end; pespCache = {} end)

-- BOSS FARM (Halloween AI boss, capture-confirmed): the boss lives in Workspace.Live like a player, e.g.
-- "AI_Shin Eva Godzilla_1", with attributes IsBoss/IsAI and the CollectionService tag "BossBarTarget".
-- Flow (capture-confirmed): players gather at Workspace.Map.BossPortal in Antarctica (~1928,71,875); its
-- attributes drive everything (State, NextSpawnAt, GatherAt, PlayersAtPortal, MinPlayers=3, PlayersInRoom,
-- Open). At NextSpawnAt the game teleports the gathered players into the boss room (~-9690,1203,-4699).
-- Damage is server-side from skills at our HRP (same as PvP), so we track the boss per frame and spam
-- skills. Waiting = standing on the portal. Dying -> auto respawn (the game returns you to the room while
-- the boss lives). Scoped in a do-block for the 200-local limit.
do
    local CS = game:GetService("CollectionService")
    local ROOM = Vector3.new(-9690, 1203, -4699)     -- boss room (game teleports you here at spawn)
    local PORTAL_POS = Vector3.new(1928, 71, 875)     -- BossPortal fallback when it hasn't streamed in yet
    local BossTab = Window:AddTab("Boss", "skull")
    local BossBox = BossTab:AddLeftGroupbox("Boss Farm")
    BossBox:AddToggle("k_bossfarm", { Text = "Boss Farm", Default = false,
        Tooltip = "Fights the Halloween boss for you and respawns you if you die.",
        Callback = function(on)
            if on then
                if Toggles.k_farm and Toggles.k_farm.Value then Toggles.k_farm:SetValue(false) end
                if Toggles.k_pvp and Toggles.k_pvp.Value then Toggles.k_pvp:SetValue(false) end
                if Toggles.k_autopark and Toggles.k_autopark.Value then Toggles.k_autopark:SetValue(false) end
                if Toggles.k_beamcycle and Toggles.k_beamcycle.Value then Toggles.k_beamcycle:SetValue(false) end
            else
                maybeRestoreClip()
            end
        end })
    BossBox:AddToggle("k_boss_wait", { Text = "Wait At Boss Portal", Default = true, Tooltip = "When no boss is up, stand on the Boss Portal in Antarctica so you count toward the 3 players and get pulled into the room when it spawns." })
    BossBox:AddDropdown("k_boss_skills", { Values = SKILLS, Default = { ["Attack1"] = true, ["Attack2"] = true, ["Attack3"] = true }, Multi = true, AllowNull = true, Text = "Attacks" })
    BossBox:AddDropdown("k_boss_pos", { Values = { "Behind", "Above", "Front", "Side" }, Default = "Behind", Text = "Position", Tooltip = "Where to stand relative to the boss. Behind is safest." })
    BossBox:AddSlider("k_boss_dist", { Text = "Stand Distance", Default = 12, Min = 4, Max = 60, Rounding = 0 })
    BossBox:AddToggle("k_boss_freeze", { Text = "Freeze Boss", Default = false, Tooltip = "Pins the boss in place so it can't chase, fly or reposition. Works best when you're the closest player to it." })
    BossBox:AddToggle("k_boss_away", { Text = "Turn Boss Away", Default = false, Tooltip = "Keeps the boss facing away from you so its attacks miss. Use with Position = Behind." })
    BossBox:AddToggle("k_boss_dodge", { Text = "Auto Dodge", Default = true, Tooltip = "Lifts you out of incoming boss attacks and drops you back right after. Holds your skills while you're up." })
    BossBox:AddToggle("k_boss_hop", { Text = "Auto Hop For Boss", Default = false,
        Tooltip = "Hops to another server when the next boss here is too far off or you missed the fight. Put the script in your executor's autoexec so it keeps going after each hop." })
    BossBox:AddSlider("k_boss_hopmin", { Text = "Hop If Spawn Is Over", Default = 3, Min = 1, Max = 30, Rounding = 0, Suffix = " min" })
    BossBox:AddToggle("k_boss_skipcs", { Text = "Skip Boss Cutscene", Default = true, Tooltip = "Votes skip on the boss intro for you. It only fully skips once everyone in the fight has voted." })
    -- CUTSCENE SKIP (real source: RS.Cutscene.CutsceneClient): server starts it with Remotes.Play(name);
    -- skipping = Remotes.VoteSkip:FireServer(name, true), ratio 1 (everyone must vote). Fired directly (the
    -- module's VoteSkip() toggles, and an executor require() can hand back a separate copy that does nothing).
    task.spawn(function()
        local cs = RS:WaitForChild("Cutscene", 30)
        local rem = cs and cs:WaitForChild("Remotes", 30)
        local play = rem and rem:WaitForChild("Play", 15)
        local vote = rem and rem:WaitForChild("VoteSkip", 15)
        if not (play and vote) then return end
        track(play.OnClientEvent:Connect(function(name)
            if not (Toggles.k_boss_skipcs and Toggles.k_boss_skipcs.Value) then return end
            task.wait(1)   -- let the game register the cutscene before voting
            pcall(function() vote:FireServer(name, true) end)
        end))
    end)
    local portalRef = nil
    local function findPortal()
        if portalRef and portalRef.Parent then return portalRef end
        local map = Workspace:FindFirstChild("Map")
        local p = map and map:FindFirstChild("BossPortal")
        if not p and map then
            for _, c in ipairs(map:GetChildren()) do
                if c:IsA("BasePart") and c:GetAttribute("MinPlayers") ~= nil and c:GetAttribute("NextSpawnAt") ~= nil then p = c; break end
            end
        end
        portalRef = p
        return p
    end
    local function portalCF()
        local p = findPortal()
        return CFrame.new(((p and p.Position) or PORTAL_POS) + Vector3.new(0, 5, 0))
    end
    BossBox:AddButton({ Text = "Teleport To Boss Portal", Func = function()
        local rp = rootPart()
        if not rp then notify("You are not spawned"); return end
        rp.CFrame = portalCF(); rp.AssemblyLinearVelocity = Vector3.zero
    end })
    local InfoBoxB = BossTab:AddRightGroupbox("Boss Status")
    local lblBoss = InfoBoxB:AddLabel("Boss: none", true)
    local lblDmg = InfoBoxB:AddLabel("Your damage: -", true)
    local lblTimer = InfoBoxB:AddLabel("Next spawn: -", true)
    local lblLock = InfoBoxB:AddLabel("AI: -", true)

    local function findBoss()
        local live = Workspace:FindFirstChild("Live")
        if live then
            for _, m in ipairs(live:GetChildren()) do
                if m:IsA("Model") and m:GetAttribute("IsBoss") == true then
                    local h = m:FindFirstChildWhichIsA("Humanoid")
                    local rp = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart")
                    if h and rp and h.Health > 0 then return m, h, rp end
                end
            end
        end
        for _, m in ipairs(CS:GetTagged("BossBarTarget")) do
            if m:IsA("Model") then
                local h = m:FindFirstChildWhichIsA("Humanoid")
                local rp = m.PrimaryPart or m:FindFirstChild("HumanoidRootPart")
                if h and rp and h.Health > 0 then return m, h, rp end
            end
        end
        return nil
    end
    local function bossStand(rp)
        local pos, ecf = rp.Position, rp.CFrame
        local d = (Opt.k_boss_dist and Opt.k_boss_dist.Value) or 12
        local mode = (Opt.k_boss_pos and Opt.k_boss_pos.Value) or "Behind"
        local sp
        if mode == "Above" then sp = pos + Vector3.new(0, math.max(d, 10), -2)
        elseif mode == "Front" then sp = pos + ecf.LookVector * d
        elseif mode == "Side" then sp = pos + ecf.RightVector * d
        else sp = pos - ecf.LookVector * d end
        if mode ~= "Above" then sp = Vector3.new(sp.X, pos.Y, sp.Z) end
        return CFrame.lookAt(sp, pos)
    end

    local bossRp = nil
    local graceUntil = 0   -- after a respawn the game itself returns you to the arena while the boss lives; don't fight it
    local function bossOn() return Toggles.k_bossfarm and Toggles.k_bossfarm.Value end
    local clipped = false   -- true while noclip is on for the fight; restored before waiting so we land on the ground
    -- BOSS CONTROL (capture-confirmed: isnetworkowner(boss root)=true, ReceiveAge=0). The server's AI moves
    -- the boss with AIFlightAlign (AlignPosition) + AIBossFacingAlign (AlignOrientation) on its root, but the
    -- physics run on OUR client, so whatever CFrame we give the root is what the server sees -- including
    -- where it builds the boss's attack hitboxes. We disable those movers locally and drive the root.
    local ino = isnetworkowner or (getgenv and getgenv().isnetworkowner)
    local function ownsBoss(part)
        if ino then local ok, r = pcall(ino, part); if ok then return r == true end end
        local ok, age = pcall(function() return part.ReceiveAge end)
        return ok and age == 0
    end
    local movers, frozenAt = {}, nil
    local function releaseMovers()
        for m in pairs(movers) do pcall(function() m.Enabled = true end) end
        movers = {}
    end
    local function controlBoss(brp, myPos)
        local freeze = Toggles.k_boss_freeze and Toggles.k_boss_freeze.Value
        local away = Toggles.k_boss_away and Toggles.k_boss_away.Value
        if not (freeze or away) or not ownsBoss(brp) then
            frozenAt = nil
            if next(movers) then releaseMovers() end
            return
        end
        for _, c in ipairs(brp:GetChildren()) do
            if (c:IsA("AlignPosition") or c:IsA("AlignOrientation")) and c.Enabled then movers[c] = true; c.Enabled = false end
        end
        if freeze then frozenAt = frozenAt or brp.Position else frozenAt = nil end
        local pos = frozenAt or brp.Position
        local look = brp.CFrame.LookVector
        if away then
            local d = Vector3.new(pos.X - myPos.X, 0, pos.Z - myPos.Z)
            if d.Magnitude > 0.1 then look = d.Unit end
        end
        brp.CFrame = CFrame.lookAt(pos, pos + Vector3.new(look.X, 0, look.Z))
        brp.AssemblyLinearVelocity = Vector3.zero
        brp.AssemblyAngularVelocity = Vector3.zero
    end
    onClean(releaseMovers)
    -- AUTO DODGE v2 (built from boss_deep_dump, 2026-09-30):
    -- * Every boss move is in RS.Shared.KaijuData[<kaiju>].AttackStatics[move].HitboxData (BasePart, Offset,
    --   Size). The boss model is scaled (~1.7x), so the real hitbox = data * scale (25.5x34x25.5 = 15x20x15).
    -- * Each attack animation is named after its move (KaijuData.<kaiju>.Animation.<move>), so the moment the
    --   boss starts a move we know where its hitbox will be and leave BEFORE it spawns. Reacting to the hitbox
    --   part alone was too late: it lives ~0.3s and the server judges the hit on our already-replicated spot.
    -- * Real boss hitbox parts are the second layer. Other players' Hitbox_<player> parts are ignored -- the
    --   old dodge reacted to them (72 per 2 min around the boss) and jumped for nothing.
    -- * We only go up while a predicted/real box covers our fighting spot, just high enough to clear it,
    --   come back 0.35s after it's gone, and don't waste skills while up.
    -- v3 (phase-3 deep dump): the AI boss's real hitboxes don't always match KaijuData (phase-3 specials spawn
    --   85x51x102 @ boss-local z -37, data said 85^3 @ z -25 -> it covered Behind 20 and we floated at ~100
    --   studs for every special while nothing could reach us). So each move LEARNS its real hitbox (offset from
    --   the boss root, size, delay after the anim starts) the first time it lands and predicts from that,
    --   and only goes up in the short window around when it lands. KaijuData is just the first-time guess.
    --   The spear throw (BossSpearThrown) is NOT dodged any more: it explodes ON its target ~2.1s later
    --   wherever they are (SpearExplode spawned at our position 147 studs up) -- going up only cost DPS.
    local DG = { hold = 0, height = 150, up = false, pending = {}, live = {}, animName = {}, scale = 1.7, learn = {} }
    local function dodgeOn() return bossOn() and Toggles.k_boss_dodge and Toggles.k_boss_dodge.Value end
    local function insideBox(cf, size, pos, margin)
        local l = cf:PointToObjectSpace(pos)
        local h = size / 2 + Vector3.new(margin, margin, margin)
        return math.abs(l.X) <= h.X and math.abs(l.Y) <= h.Y and math.abs(l.Z) <= h.Z
    end
    function DG.onAnim(tr)
        if not tr.Looped then DG.lastAttack = os.clock() end
        if not dodgeOn() then return end
        local id = ""
        pcall(function() id = tr.Animation.AnimationId end)
        local name = DG.animName[id]
        if not name then return end
        name = name:gsub("Moving$", "")
        local mv = DG.moves and DG.moves[name]
        if type(mv) ~= "table" or type(mv.HitboxData) ~= "table" then return end
        local len = (tr.Length and tr.Length > 0) and tr.Length or 2
        local now = os.clock()
        local L = DG.learn[name]
        -- lock capture: Attack5Special's 136x68x136 nuke landed 5.1s after its anim started (one-shot all 3
        -- players for 4444) -- the old 0.5s-past-anim window had already expired by then
        local expire = now + math.clamp(len + 1.5, 2, 8)
        if L then expire = math.max(expire, now + L.delay + 1.2) end
        table.insert(DG.pending, { name = name, hd = mv.HitboxData, t = now, expire = expire })
    end
    function DG.load(bm)
        if DG.model == bm then return end
        DG.model, DG.moves, DG.animName, DG.pending, DG.live = bm, nil, {}, {}, {}   -- DG.learn survives respawned bosses
        local kd = RS:FindFirstChild("Shared")
        kd = kd and kd:FindFirstChild("KaijuData")
        local kn = bm:GetAttribute("KaijuName")
        local mod = kd and type(kn) == "string" and kd:FindFirstChild(kn)
        if not mod then return end
        local ok, data = pcall(require, mod)
        if ok and type(data) == "table" then
            local t = type(data.KaijuData) == "table" and data.KaijuData or data
            DG.moves = t.AttackStatics
        end
        local af = mod:FindFirstChild("Animation")
        if af then
            for _, a in ipairs(af:GetChildren()) do
                if a:IsA("Animation") then DG.animName[a.AnimationId] = a.Name end
            end
        end
        local okS, s = pcall(function() return bm:GetScale() end)
        if okS and type(s) == "number" and s > 1.05 then DG.scale = s end
        -- one boss at a time: drop the last boss's listeners instead of piling them up in CONNS all session
        for _, c in ipairs(DG.animConns or {}) do pcall(function() c:Disconnect() end) end
        DG.animConns = {}
        for _, an in ipairs(bm:GetDescendants()) do
            if an:IsA("Animator") then table.insert(DG.animConns, an.AnimationPlayed:Connect(DG.onAnim)) end
        end
    end
    onClean(function() for _, c in ipairs(DG.animConns or {}) do pcall(function() c:Disconnect() end) end end)
    function DG.predBox(hd)
        local base = (hd.BasePart == nil or hd.BasePart == "HumanoidRootPart") and bossRp
            or (DG.model and DG.model:FindFirstChild(hd.BasePart, true))
        if not (base and base:IsA("BasePart")) then return end
        local off = typeof(hd.Offset) == "CFrame" and hd.Offset or CFrame.new()
        local sz = typeof(hd.Size) == "Vector3" and hd.Size or Vector3.new(20, 20, 20)
        return base.CFrame * (CFrame.new(off.Position * DG.scale) * off.Rotation), sz * DG.scale, base ~= bossRp
    end
    function DG.threat(spot)
        local now, top = os.clock(), nil
        for part in pairs(DG.live) do
            if not part.Parent then
                DG.live[part] = nil
            elseif insideBox(part.CFrame, part.Size, spot, 6) then
                local t = part.Position.Y + part.Size.Y / 2
                top = math.max(top or t, t)
            end
        end
        for i = #DG.pending, 1, -1 do
            local e = DG.pending[i]
            if now > e.expire or (e.box and not e.box.Parent) then
                table.remove(DG.pending, i)
            elseif not e.box then
                local L = DG.learn[e.name]
                local cf, size, margin
                if L and bossRp then
                    local dt = now - e.t
                    if dt >= L.delay - 0.5 and dt <= L.delay + 0.8 then   -- only around when it actually lands
                        cf, size, margin = bossRp.CFrame * L.cf, L.size, 6
                    end
                else
                    local loose
                    cf, size, loose = DG.predBox(e.hd)
                    margin = loose and 10 or 6   -- non-root parts (Tail6, spear) swing: wider margin
                end
                if cf and insideBox(cf, size, spot, margin) then
                    local t = cf.Position.Y + size.Y / 2
                    top = math.max(top or t, t)
                end
            end
        end
        if top then
            DG.hold = now + 0.35   -- damage lands ~0.3s after a hitbox spawns; stay up a beat past it
            DG.height = math.clamp(top - spot.Y + 25, 60, 400)
        end
        return now < DG.hold
    end
    track(Workspace.DescendantAdded:Connect(function(d)
        local nm = d.Name
        if nm:sub(1, 7) ~= "Hitbox_" or not dodgeOn() or not d:IsA("BasePart") then return end
        if not (d.Parent and d.Parent.Name == "Debris") or Players:FindFirstChild(nm:sub(8)) then return end
        DG.live[d] = true
        for i = #DG.pending, 1, -1 do   -- newest move without a hitbox yet = the one that spawned it
            local e = DG.pending[i]
            if not e.box then
                e.box = d
                local hs = e.hd.Size
                if e.hd.BasePart == "HumanoidRootPart" and typeof(hs) == "Vector3" and hs.Y > 0 then
                    local r = d.Size.Y / hs.Y
                    if r > 1.1 and r < 4 then DG.scale = r end
                end
                if bossRp and bossRp.Parent then
                    local delay = os.clock() - e.t
                    local L = DG.learn[e.name]
                    DG.learn[e.name] = {
                        cf = bossRp.CFrame:ToObjectSpace(d.CFrame), size = d.Size,
                        delay = L and (L.delay * 0.6 + delay * 0.4) or delay,
                    }
                end
                break
            end
        end
    end))
    track(RunService.Heartbeat:Connect(function()
        if not bossOn() or archBusy or not isSpawned() then
            if next(movers) then releaseMovers(); frozenAt = nil end
            return
        end
        local rp = rootPart(); if not rp then return end
        if bossRp and bossRp.Parent then
            pcall(controlBoss, bossRp, rp.Position)
            noclipChar(); clipped = true
            local cf = bossStand(bossRp)
            DG.up = dodgeOn() and DG.threat(cf.Position) or false
            if DG.up then cf = cf + Vector3.new(0, DG.height, 0) end
            rp.CFrame = cf
            rp.AssemblyLinearVelocity = Vector3.zero
            rp.AssemblyAngularVelocity = Vector3.zero
        else
            -- no boss (dead / not up): give collision back right away, or we'd fall through the room floor
            if clipped then restoreClip(); clipped = false end
            if os.clock() > graceUntil and Toggles.k_boss_wait and Toggles.k_boss_wait.Value
                and (rp.Position - ROOM).Magnitude > 1500 then   -- never yank out of the boss room; only wait at the portal
                local pc = portalCF().Position
                -- teleport once and let gravity drop us onto the portal; only re-teleport if we drift away
                if Vector3.new(rp.Position.X - pc.X, 0, rp.Position.Z - pc.Z).Magnitude > 20 then
                    rp.CFrame = CFrame.new(pc)
                    rp.AssemblyLinearVelocity = Vector3.zero
                end
            end
        end
    end))
    task.spawn(function()
        while RUNNING do
            if bossOn() then
                if not isSpawned() then
                    bossRp = nil
                    if not respawning then ensureRespawn((Opt.k_island and Opt.k_island.Value) or "Tokyo") end
                    graceUntil = os.clock() + 8   -- let the game place us back in the arena before we pin anywhere
                    task.wait(0.5)
                else
                    local m, h, rp = findBoss()
                    bossRp = rp
                    if m then
                        pcall(DG.load, m)
                        if not DG.up then fireReadySkill("k_boss_skills") end
                        task.wait((Opt.k_farmdelay and Opt.k_farmdelay.Value) or 0.1)
                    else
                        task.wait(0.5)
                    end
                end
            else
                bossRp = nil
                task.wait(0.5)
            end
        end
    end)

    task.spawn(function()
        while RUNNING do
            pcall(function()
                local m, h = findBoss()
                if m then
                    lblBoss:SetText(("Boss: %s  |  HP %d / %d  |  Phase %s"):format(tostring(m:GetAttribute("BossName") or m.Name), math.floor(h.Health), math.floor(h.MaxHealth), tostring(m:GetAttribute("BossPhase") or "?")))
                    -- AI LOCK (boss_lock_capture): the AI only attacks once AIBossFacingAlign has turned the boss
                    -- to its target. Every player behind + Turn Away on every script client = it never gets
                    -- there, so it stands still and stops attacking (66s with 0 attacks). Its beam
                    -- (Attack4Special) still fires without facing and can break the lock.
                    local idle = DG.lastAttack and (os.clock() - DG.lastAttack) or 0
                    lblLock:SetText(idle >= 12 and ("AI: LOCKED  (no attacks for %ds)"):format(math.floor(idle)) or "AI: attacking")
                    local pct = "-"
                    local ok, board = pcall(function() return HttpService:JSONDecode(m:GetAttribute("DamageBoard") or "[]") end)
                    if ok and type(board) == "table" then
                        for _, row in ipairs(board) do
                            if row.u == lp.UserId then pct = ("%.2f%%  (%d dmg)"):format((row.p or 0) / 100, row.d or 0) end
                        end
                    end
                    lblDmg:SetText("Your damage: " .. pct)
                else
                    lblBoss:SetText("Boss: none up")
                    lblDmg:SetText("Your damage: -")
                end
                local p = findPortal()
                if p then
                    local left = (tonumber(p:GetAttribute("NextSpawnAt")) or 0) - Workspace:GetServerTimeNow()
                    local t = left > 0 and ("%02d:%02d"):format(math.floor(left / 60), math.floor(left % 60)) or "now"
                    lblTimer:SetText(("Portal: %s  |  spawn in %s  |  %s/%s at portal  |  %s in room"):format(
                        tostring(p:GetAttribute("State") or "?"), t, tostring(p:GetAttribute("PlayersAtPortal") or 0),
                        tostring(p:GetAttribute("MinPlayers") or 3), tostring(p:GetAttribute("PlayersInRoom") or 0)))
                else
                    lblTimer:SetText("Portal: not loaded (go to Antarctica / use the button)")
                end
            end)
            task.wait(0.5)
        end
    end)

    -- AUTO HOP FOR BOSS: the portal's NextSpawnAt (server time) says how long until the next fight here.
    -- The boss room is ~11k studs from the portal, so with StreamingEnabled findBoss() is nil while we wait
    -- even if a fight is running -- "spawn time passed 90s ago and we're still outside" = we missed it.
    task.spawn(function()
        local joinedAt, missedSince = os.clock(), nil
        while RUNNING do
            task.wait(2)
            local on = bossOn() and Toggles.k_boss_hop and Toggles.k_boss_hop.Value
            local p = on and os.clock() - joinedAt > 25 and isSpawned() and not findBoss() and findPortal()
            if p then
                local left = (tonumber(p:GetAttribute("NextSpawnAt")) or 0) - Workspace:GetServerTimeNow()
                local limit = ((Opt.k_boss_hopmin and Opt.k_boss_hopmin.Value) or 3) * 60
                local why
                if left > limit then
                    why = ("next boss in %d min"):format(math.floor(left / 60))
                    missedSince = nil
                elseif left <= 0 then
                    missedSince = missedSince or os.clock()
                    if os.clock() - missedSince > 90 then why = "missed this server's fight" end
                else
                    missedSince = nil
                end
                if why and pvpHop then
                    notify("Boss hop: " .. why)
                    pvpHop(5, "Boss hop")
                    joinedAt, missedSince = os.clock(), nil   -- teleport failed or pending: wait before retrying
                end
            else
                missedSince = nil
            end
        end
    end)
end

-- AIM + STREAMER tabs (merged from the standalone kaiju_beam_aim.lua). Wrapped in an anonymous function
-- so its locals get their own register budget instead of eating the main chunk's 200-local limit.
-- BEAM AIM: the game's FireBeam loop (PlayerScripts Control) sends Mouse.Hit.Position to
-- Remotes.GetMousePos every ~0.01s while CombatRemote "DoBeam" is on, and turns your kaiju toward it.
-- Touch devices go through GetWorldHitFromScreen -> Camera:ScreenPointToRay instead of the mouse.
-- We redirect all three (Mouse.Hit, the GetMousePos arg, the camera ray) at the locked target, and can
-- lock the camera on it (during a beam the game rotates you CameraRelative).
-- STREAMER: rewrites any on-screen text that shows your name / cells (HUD, menus, boss board, tags),
-- re-masks whenever the game updates a label, and restores everything when turned off / unloaded.
;(function()
    local StarterGui = game:GetService("StarterGui")
    local TextChatService = game:GetService("TextChatService")
    local mouse = lp:GetMouse()
    local GetMousePos = Remotes:FindFirstChild("GetMousePos")
    local IS_MOBILE = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
    local S = { run = true, spoof = false, aimPos = nil, aimCF = nil, target = nil, beamOn = false, beamAt = 0, cam = Workspace.CurrentCamera }
    local hl, quickGui
    local function live() return Workspace:FindFirstChild("Live") end
    local function rootOf(m) return m and (m.PrimaryPart or m:FindFirstChild("HumanoidRootPart")) end
    local function alive(m) local h = m and m:FindFirstChildWhichIsA("Humanoid"); return h ~= nil and h.Health > 0 end
    local function guiParent()
        local ok, h = pcall(function() return gethui and gethui() end)
        if ok and h then return h end
        return game:GetService("CoreGui")
    end
    local function playerNames()
        local n = {}
        for _, p in ipairs(Players:GetPlayers()) do if p ~= lp then n[#n + 1] = p.Name end end
        table.sort(n)
        return n
    end
    onClean(function()
        S.run, S.spoof = false, false
        pcall(function() RunService:UnbindFromRenderStep("CW_BeamCam") end)
        if hl then pcall(function() hl:Destroy() end) end
        if quickGui then pcall(function() quickGui:Destroy() end) end
    end)

    local AimTab = Window:AddTab("Aim", "target")
    local TargetBox = AimTab:AddLeftGroupbox("Target")
    TargetBox:AddDropdown("beam_mode", { Text = "Lock On", Values = { "Boss > Nearest", "Boss", "Nearest Player", "Nearest To Crosshair", "Selected Player" }, Default = "Boss > Nearest" })
    TargetBox:AddDropdown("beam_player", { Text = "Selected Player", Values = playerNames(), Default = nil, AllowNull = true })
    TargetBox:AddButton({ Text = "Refresh Players", Func = function() Opt.beam_player:SetValues(playerNames()) end })
    TargetBox:AddDivider()
    TargetBox:AddDropdown("beam_part", { Text = "Aim At", Values = { "Body", "Head", "Root" }, Default = "Body" })
    TargetBox:AddSlider("beam_range", { Text = "Max Range", Default = 1500, Min = 100, Max = 5000, Rounding = 0, Suffix = " studs" })
    local LockBox = AimTab:AddRightGroupbox("Beam Lock")
    LockBox:AddToggle("beam_aim", { Text = "Beam Aim Lock", Default = true, Tooltip = "Your beam follows the target instead of your mouse / screen (PC + mobile)." })
    LockBox:AddToggle("beam_cam", { Text = "Camera Lock", Default = true, Tooltip = "Camera follows the target. While beaming your kaiju turns with the camera." })
    LockBox:AddDropdown("beam_when", { Text = "Active", Values = { "While Beaming", "Always" }, Default = "While Beaming" })
    LockBox:AddDivider()
    LockBox:AddSlider("beam_lead", { Text = "Lead", Default = 0.15, Min = 0, Max = 1, Rounding = 2, Suffix = "s", Tooltip = "Aims ahead of moving targets." })
    LockBox:AddToggle("beam_hl", { Text = "Highlight Target", Default = true })
    LockBox:AddToggle("beam_quick", { Text = "Quick AIM Button", Default = IS_MOBILE, Tooltip = "Small draggable on-screen button to switch the aim lock mid-fight (on by default on mobile)." })

    local function findBoss()
        local lf = live()
        if not lf then return nil end
        for _, m in ipairs(lf:GetChildren()) do
            if m:GetAttribute("IsBoss") == true and alive(m) then return m end
        end
    end
    local function pickTarget()
        local lf = live()
        if not lf then return nil end
        local mode = Opt.beam_mode.Value
        if mode == "Boss" then return findBoss() end
        if mode == "Boss > Nearest" then
            local b = findBoss()
            if b then return b end
        end
        if mode == "Selected Player" then
            local m = lf:FindFirstChild(Opt.beam_player.Value or "")
            return alive(m) and m or nil
        end
        local me = rootPart()
        if not me then return nil end
        local cam = S.cam
        local vp = cam.ViewportSize
        local center = IS_MOBILE and Vector2.new(vp.X / 2, vp.Y / 2) or UserInputService:GetMouseLocation()
        local maxR = Opt.beam_range.Value
        local best, bestD
        for _, m in ipairs(lf:GetChildren()) do
            if m.Name ~= lp.Name and m:GetAttribute("IsBoss") ~= true and Players:FindFirstChild(m.Name) and alive(m) then
                local r = rootOf(m)
                if r and (r.Position - me.Position).Magnitude <= maxR then
                    local d
                    if mode == "Nearest To Crosshair" then
                        local sp, on = cam:WorldToViewportPoint(r.Position)
                        if on then d = (Vector2.new(sp.X, sp.Y) - center).Magnitude end
                    else
                        d = (r.Position - me.Position).Magnitude
                    end
                    if d and (not bestD or d < bestD) then best, bestD = m, d end
                end
            end
        end
        return best
    end
    local BODY = { "CamPart", "UpperBody", "MainBody", "Chest", "UpperTorso", "Torso", "Body" }
    local partCache = setmetatable({}, { __mode = "k" })
    local function aimPart(m)
        local which = Opt.beam_part.Value
        local c = partCache[m]
        if c and c.which == which and c.part.Parent then return c.part end
        local part
        if which == "Head" then
            local h = m:FindFirstChild("Head", true)
            if h and h:IsA("BasePart") then part = h end
        elseif which == "Body" then
            for _, n in ipairs(BODY) do
                local p = m:FindFirstChild(n, true)
                if p and p:IsA("BasePart") then part = p; break end
            end
        end
        part = part or rootOf(m)
        if part then partCache[m] = { which = which, part = part } end
        return part
    end

    track(CombatRemote.OnClientEvent:Connect(function(a, b)
        if a == "DoBeam" then
            S.beamOn = b == true
            if S.beamOn then S.beamAt = os.clock() end
        end
    end))
    local hookmm = hookmetamethod or (getgenv and getgenv().hookmetamethod)
    local ncm = getnamecallmethod or (getgenv and getgenv().getnamecallmethod)
    local cc = checkcaller or function() return false end
    local ncc = newcclosure or function(f) return f end
    -- hooks are installed ONCE per game session and read the live state through _G, so re-executing the
    -- script swaps in the new state instead of stacking another pair of game-wide hooks every time.
    -- LAG FIX (flight kaiju stutter): they sit on EVERY property read / method call the game makes, and the
    -- flight controller runs heavy per-frame code -- so they're now only installed the first time the aim
    -- lock is actually used, not at load for everyone.
    local HS = _G.__CW_AIM_HOOK
    if HS then HS.S = S end
    local function installHooks()
        if HS or not (hookmm and ncm) then return end
        HS = { S = S }
        _G.__CW_AIM_HOOK = HS
        local oldIdx
        oldIdx = hookmm(game, "__index", ncc(function(self, k)
            if k ~= "Hit" and k ~= "hit" then return oldIdx(self, k) end   -- cheapest possible exit first
            local S = HS.S
            if S.spoof and self == mouse and not cc() then
                local cf = S.aimCF
                if cf then return cf end
            end
            return oldIdx(self, k)
        end))
        local oldNc
        oldNc = hookmm(game, "__namecall", ncc(function(self, ...)
            local S = HS.S
            if S.spoof and not cc() then
                local p = S.aimPos
                if p then
                    -- real Control.lua: while beaming it fires BeamRemote:FireServer(hitPos) every frame (this is
                    -- what actually steers the beam); hitPos = touch->ScreenPointToRay raycast or Mouse.Hit. The
                    -- raycast can stop on a building in between, so rewrite the beam point itself too.
                    if (GetMousePos and self == GetMousePos) or self == BeamRemote then
                        if ncm() == "FireServer" then return oldNc(self, p) end
                    elseif self == S.cam then
                        local m = ncm()
                        if m == "ScreenPointToRay" then
                            local o = S.cam.CFrame.Position
                            local dir = p - o
                            if dir.Magnitude > 0.1 then return Ray.new(o, dir.Unit) end
                        end
