                end
            end
            return oldNc(self, ...)
        end))
    end

    local function beaming() return S.beamOn and os.clock() - S.beamAt < 15 end
    local function lockActive() return Opt.beam_when.Value == "Always" or beaming() end
    track(RunService.Heartbeat:Connect(function()
        if not S.run then return end
        S.cam = Workspace.CurrentCamera
        if BEAMCTL.pos then   -- a building sweep (Auto Beam / Beam Cycle) is steering the beam: it wins
            local p = BEAMCTL.pos
            local dir = p - S.cam.CFrame.Position
            S.target, S.aimPos = nil, p
            S.aimCF = dir.Magnitude > 0.1 and CFrame.lookAt(p, p + dir.Unit) or CFrame.new(p)
            S.spoof = true
            if not HS then installHooks() end
            return
        end
        -- only search for a target while it can be used (beaming, or Active = Always) -- not every frame forever;
        -- building farm has its own Auto Beam (BeamRemote sweep), so don't pull the beam onto players there
        local t = (not farming and lockActive() and (Toggles.beam_aim.Value or Toggles.beam_cam.Value)) and pickTarget() or nil
        S.target = t
        local part = t and aimPart(t)
        if part then
            local p = part.Position + part.AssemblyLinearVelocity * Opt.beam_lead.Value
            S.aimPos = p
            local dir = p - S.cam.CFrame.Position
            S.aimCF = dir.Magnitude > 0.1 and CFrame.lookAt(p, p + dir.Unit) or CFrame.new(p)
        else
            S.aimPos, S.aimCF = nil, nil
        end
        S.spoof = Toggles.beam_aim.Value and S.aimPos ~= nil and lockActive()
