    local StatBox = StreamTab:AddRightGroupbox("Stats")
    StatBox:AddToggle("sm_cells", { Text = "Hide Cells", Default = false, Tooltip = "Any format: 1234567 / 1,234,567 / 1.2M, plus cells counters on the HUD." })
    StatBox:AddToggle("sm_level", { Text = "Hide Level", Default = false, Tooltip = "\"Level 200\", \"Lv. 200\", \"[Lvl 200]\" and level counters." })
    StatBox:AddToggle("sm_kills", { Text = "Hide Kills", Default = false })
    StatBox:AddToggle("sm_exp", { Text = "Hide EXP", Default = false, Tooltip = "EXP / XP amounts and bars' numbers." })
    StatBox:AddToggle("sm_stats", { Text = "Hide Other Stats", Default = false, Tooltip = "Deaths, damage dealt, playtime, buildings destroyed." })
    StatBox:AddToggle("sm_items", { Text = "Hide Item Counts", Default = false, Tooltip = "Inventory amounts (DNA, skulls, boosts, archetype tokens)." })

    local orig = setmetatable({}, { __mode = "k" })      -- obj -> the game's real text
    local written = setmetatable({}, { __mode = "k" })   -- obj -> what we last wrote
    local watched = setmetatable({}, { __mode = "k" })
    local busy = false
    local names, cellPats, cellAt = {}, {}, 0
    local function esc(s) return (s:gsub("[%p%^%$]", "%%%0")) end
    local function commas(n)
        local s = tostring(math.floor(n)):reverse():gsub("(%d%d%d)", "%1,"):reverse()
        return (s:gsub("^,", ""))
    end
    local function refreshCellPats()
        if os.clock() - cellAt < 1 then return end
        cellAt = os.clock()
        local list, seen = {}, {}
        local function addp(s) if s and #s >= 2 and not seen[s] then seen[s] = true; list[#list + 1] = s end end
        local c = getCells()
        if c and c >= 10 then
            addp(tostring(math.floor(c)))
            addp(commas(c))
            for _, u in ipairs({ { 1e12, "T" }, { 1e9, "B" }, { 1e6, "M" }, { 1e3, "K" } }) do
                if c >= u[1] then
                    local v = c / u[1]
                    addp(("%.2f"):format(v) .. u[2]); addp(("%.1f"):format(v) .. u[2]); addp(("%d"):format(math.floor(v)) .. u[2])
                    addp(("%.2f"):format(v) .. u[2]:lower()); addp(("%.1f"):format(v) .. u[2]:lower())
                    break
                end
            end
        end
        local ls = lp:FindFirstChild("leaderstats")
        local lc = ls and ls:FindFirstChild("Cells")
        if lc and tostring(lc.Value) ~= "0" then addp(tostring(lc.Value)) end
        table.sort(list, function(a, b) return #a > #b end)   -- longest first so "1.25M" wins over "1.2"
        cellPats = list
    end
    local function nameList()
        local l = {}
        if Toggles.sm_name.Value then
            local fake = (Opt.sm_fake.Value ~= "" and Opt.sm_fake.Value) or "Kaiju"
            l[#l + 1] = { lp.Name, fake }
            if lp.DisplayName ~= lp.Name then l[#l + 1] = { lp.DisplayName, fake } end
            l[#l + 1] = { tostring(lp.UserId), "0" }
        end
        if Toggles.sm_others.Value then
            local i = 0
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= lp then
                    i = i + 1
                    l[#l + 1] = { p.Name, "Player " .. i }
                    if p.DisplayName ~= p.Name then l[#l + 1] = { p.DisplayName, "Player " .. i } end
                end
            end
        end
        table.sort(l, function(a, b) return #a[1] > #b[1] end)
        return l
    end
    -- each stat: words that mark a counter label (obj or its 2 parents named e.g. "LevelLabel"/"Kills")
    -- -> mask every number in it; pats catch the stat when it's inline text ("Level 200", "Kills: 12")
    local NUM = "%d[%d%.,]*%s*[KkMmBbTt]?"
    local STATS = {
        { key = "sm_cells", words = { "cell", "currency", "money" }, pats = {} },
        { key = "sm_level", words = { "level", "lvl" }, pats = { "([Ll][Ee][Vv][Ee][Ll]%s*:?%s*)%d+", "([Ll][Vv][Ll]?%.?%s*:?%s*)%d+" } },
        { key = "sm_kills", words = { "kill" }, pats = { "([Kk][Ii][Ll][Ll][Ss]?%s*:?%s*)[%d,]+" } },
        { key = "sm_exp", words = { "exp", "xp" }, pats = { "([Ee][Xx][Pp]%s*:?%s*%[?)[%d%.,]+%s*/%s*[%d%.,]+[KkMmBb]?", "([Ee]?[Xx][Pp]%s*:?%s*%[?)[%d%.,]+[KkMmBb]?" } },
        { key = "sm_stats", words = { "death", "damage", "time_played", "playtime", "building", "time" }, pats = { "([Dd][Ee][Aa][Tt][Hh][Ss]?%s*:?%s*)[%d,]+", "([Dd][Aa][Mm][Aa][Gg][Ee]%s*:?%s*)[%d%.,]+[KkMmBb]?" } },
        { key = "sm_items", words = { "inventory", "amount", "count", "dna", "skull", "boost", "token" }, pats = { "(%f[%w][xX]%s*)%d+" } },
    }
    local function ctxHas(obj, words)
        local p, n = obj, 0
        while p and n < 3 do
            local nm = p.Name:lower()
            for _, w in ipairs(words) do if nm:find(w, 1, true) then return true end end
            p, n = p.Parent, n + 1
        end
        return false
    end
    local function transform(text, obj)
        local out = text
        for _, pair in ipairs(names) do
            if #pair[1] >= 3 then out = out:gsub(esc(pair[1]), (pair[2]:gsub("%%", "%%%%"))) end
        end
        if Toggles.sm_cells.Value then
            for _, pat in ipairs(cellPats) do out = out:gsub(esc(pat), "•••") end
        end
        for _, st in ipairs(STATS) do
            if Toggles[st.key].Value then
                if ctxHas(obj, st.words) then
                    out = out:gsub(NUM, "••")
                else
                    for _, pat in ipairs(st.pats) do out = out:gsub(pat, "%1••") end
                end
            end
        end
        return out
    end
    local function anyOn()
        if Toggles.sm_name.Value or Toggles.sm_others.Value then return true end
        for _, st in ipairs(STATS) do if Toggles[st.key].Value then return true end end
        return false
    end
    local function apply(obj)
        if busy or not obj.Parent then return end
        local ok, cur = pcall(function() return obj.Text end)
        if not ok then return end
        if written[obj] ~= cur then orig[obj] = cur end   -- the game changed it: that's the new real text
        local base = orig[obj] or cur
        local out = (S.run and anyOn()) and transform(base, obj) or base
        if out ~= cur then
            busy = true
            pcall(function() obj.Text = out end)
            busy = false
        end
        written[obj] = out
    end
    -- per-label connections live in a weak table (gone with the label), not in CONNS forever
    local textConn = setmetatable({}, { __mode = "k" })
    local function watch(obj)
        if watched[obj] or not (obj:IsA("TextLabel") or obj:IsA("TextButton")) then return end
        watched[obj] = true
        textConn[obj] = obj:GetPropertyChangedSignal("Text"):Connect(function() apply(obj) end)
        apply(obj)
    end
    onClean(function() for _, c in pairs(textConn) do pcall(function() c:Disconnect() end) end end)
    local function watchTree(root)
        for _, d in ipairs(root:GetDescendants()) do watch(d) end
        track(root.DescendantAdded:Connect(function(d) task.defer(function() if d.Parent then watch(d) end end) end))
    end
    -- LAG FIX: nothing is watched until a text-hiding toggle is actually turned on (the old version watched
    -- every label in PlayerGui + CoreGui and re-walked all of them every second = a freeze every 1s)
    local started = false
    local function ensureWatching()
        if started then return end
        started = true
        watchTree(lp:WaitForChild("PlayerGui"))
        local lf = live()
        if lf then watchTree(lf) end
    end
    local function reapplyAll()
        if anyOn() then ensureWatching() elseif not started then return end
        names = nameList()
        cellAt = 0
        refreshCellPats()
        for obj in pairs(watched) do apply(obj) end
    end
    local tagOrig = setmetatable({}, { __mode = "k" })
    local chatOrig
    local boardHidden = false
    -- the game's nametag is a server-made BillboardGui on the character (its own Hide button skips yours).
    -- Each kaiju is scanned once when the state changes; late-added tags are caught by a per-model listener
    -- instead of re-walking every part of every kaiju each second.
    local tagsHidden = false
    local tagConn = setmetatable({}, { __mode = "k" })
    local function wantFor(m)
        return tagsHidden and (m.Name == lp.Name or Toggles.sm_others.Value) and Players:FindFirstChild(m.Name) ~= nil
    end
    local function tagGui(g, want)
        if want then
            if tagOrig[g] == nil then tagOrig[g] = g.Enabled end
            g.Enabled = false
        elseif tagOrig[g] ~= nil then
            g.Enabled = tagOrig[g]
            tagOrig[g] = nil
        end
    end
    local function tagModel(m)
        local want = wantFor(m)
        local h = m:FindFirstChildWhichIsA("Humanoid")
        if h then
            if want then
                if tagOrig[h] == nil then tagOrig[h] = h.DisplayDistanceType end
                h.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
            elseif tagOrig[h] ~= nil then
                h.DisplayDistanceType = tagOrig[h]
                tagOrig[h] = nil
            end
        end
        if want or next(tagOrig) then
            for _, g in ipairs(m:GetDescendants()) do
                if g:IsA("BillboardGui") then tagGui(g, want) end
            end
        end
        if want and not tagConn[m] then
            tagConn[m] = m.DescendantAdded:Connect(function(g)   -- weak table: dies with the kaiju model
                if g:IsA("BillboardGui") then tagGui(g, wantFor(m)) end
            end)
        end
    end
    onClean(function() for _, c in pairs(tagConn) do pcall(function() c:Disconnect() end) end end)
    local function setTags(hide)
        if not hide and not tagsHidden then return end
        tagsHidden = hide
        local lf = live()
        if not lf then return end
        for _, m in ipairs(lf:GetChildren()) do tagModel(m) end
    end
    local function setChat(hide)
        pcall(function()
            local cw = TextChatService:FindFirstChildOfClass("ChatWindowConfiguration")
            local ci = TextChatService:FindFirstChildOfClass("ChatInputBarConfiguration")
            local bc = TextChatService:FindFirstChildOfClass("BubbleChatConfiguration")
            if hide then
                chatOrig = chatOrig or { cw = cw and cw.Enabled, ci = ci and ci.Enabled, bc = bc and bc.Enabled }
                if cw then cw.Enabled = false end
                if ci then ci.Enabled = false end
                if bc then bc.Enabled = false end
            elseif chatOrig then
                if cw and chatOrig.cw ~= nil then cw.Enabled = chatOrig.cw end
                if ci and chatOrig.ci ~= nil then ci.Enabled = chatOrig.ci end
                if bc and chatOrig.bc ~= nil then bc.Enabled = chatOrig.bc end
                chatOrig = nil
            end
        end)
        if hide or chatOrig == nil then pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, not hide) end) end
    end
    local chatHidden = false
    local function enforce()
        local hideBoard = S.run and Toggles.sm_board.Value
        if hideBoard or boardHidden then
            pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, not hideBoard) end)
            boardHidden = hideBoard
        end
        setTags(S.run and Toggles.sm_tags.Value)
        local hideChat = S.run and Toggles.sm_chat.Value
        if hideChat ~= chatHidden then
            chatHidden = hideChat
            setChat(hideChat)
        end
    end
    task.spawn(function()
        for _, k in ipairs({ "sm_name", "sm_cells", "sm_level", "sm_kills", "sm_exp", "sm_stats", "sm_items" }) do Toggles[k]:OnChanged(reapplyAll) end
        Toggles.sm_others:OnChanged(function() reapplyAll(); enforce() end)   -- Obsidian keeps ONE OnChanged per toggle
        Opt.sm_fake:OnChanged(reapplyAll)
        for _, k in ipairs({ "sm_board", "sm_tags", "sm_chat" }) do Toggles[k]:OnChanged(enforce) end
        track(Players.PlayerAdded:Connect(function() task.wait(1); if anyOn() then reapplyAll() end end))
        local lf = live()
        if lf then
            track(lf.ChildAdded:Connect(function(m)   -- respawned kaiju: hide its nametag once it loads
                task.wait(1)
                if tagsHidden and m.Parent then pcall(tagModel, m) end
            end))
        end
        local lastSig = ""
        while S.run and RUNNING do
            if anyOn() then
                -- only re-mask everything when the things we hide actually changed (cells / players / name);
                -- every individual label already re-masks itself the moment the game updates it
                local sig = (Toggles.sm_cells.Value and tostring(getCells()) or "") .. "|" .. #Players:GetPlayers() .. "|" .. tostring(Opt.sm_fake.Value)   -- cells only matter when hiding cells (they change every kill)
                if sig ~= lastSig then
                    lastSig = sig
                    pcall(reapplyAll)
                end
            end
            if boardHidden then pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, false) end) end
            task.wait(1)
        end
    end)
    onClean(function()
        names = {}
        for obj in pairs(watched) do
            local o = orig[obj]
            if o and obj.Parent then pcall(function() obj.Text = o end) end
        end
        pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, true) end)
        setTags(false)
        setChat(false)
    end)
end)()

-- BEAM CYCLE: hover above the town, fire the beam, sweep it across every building, respawn (resets the
-- cooldown + refills energy), wait out the spawn shield (it blocks skills), repeat.
--   * beam moves = AttackStatics entries with HitAir and no HitboxData (the same rule the game data uses)
--   * the sweep steers the game's own per-frame beam point through BEAMCTL (see the Aim tab hooks) and also
--     fires BeamRemote itself, so each building really gets hit instead of being overwritten by your mouse
--   * spawn shield = the same check PvP uses on enemies (Spawning attribute / "Protect" highlight / ForceField)
;(function()
    FarmBox:AddDivider()
    FarmBox:AddToggle("k_beamcycle", { Text = "Beam Cycle", Default = false,
        Tooltip = "Hovers above the town, fires your beam across every building, then respawns to reset the cooldown and repeats. Uses the island picked in Map. Turns off the other farms.",
        Callback = function(on)
            if on then
                for _, k in ipairs({ "k_farm", "k_pvp", "k_bossfarm", "k_autopark" }) do
                    if Toggles[k] and Toggles[k].Value then Toggles[k]:SetValue(false) end
                end
            else
                BEAMCTL.pos = nil
                maybeRestoreClip()
            end
        end })
    FarmBox:AddSlider("k_bc_height", { Text = "Hover Height", Default = 40, Min = 10, Max = 200, Rounding = 0, Suffix = " studs" })
    FarmBox:AddSlider("k_bc_step", { Text = "Sweep Speed", Default = 0.12, Min = 0.05, Max = 0.5, Rounding = 2, Suffix = "s each" })
    local lblBC = FarmBox:AddLabel("Beam Cycle: off", true)

    local BC = { hold = nil, cycles = 0, killed = 0, t0 = nil }
    local function on() return Toggles.k_beamcycle and Toggles.k_beamcycle.Value end
    local function island() return (Opt.k_island and Opt.k_island.Value) or "Isla de Mara" end
    local function status(s)
        local per = (BC.t0 and BC.cycles > 0) and ("%.0fs/cycle"):format((os.clock() - BC.t0) / BC.cycles) or "-"
        pcall(function() lblBC:SetText(("Beam Cycle: %s\n%d cycles  |  %d buildings  |  %s"):format(s, BC.cycles, BC.killed, per)) end)
    end
    local function beamKeys()
        local as = attackStatics(currentKaiju())
        local out = {}
        if type(as) == "table" then
            for _, k in ipairs({ "Attack1", "Attack2", "Attack3", "Attack4", "Attack5", "Overdrive" }) do
                local s = as[k]
                if type(s) == "table" and s.HitAir ~= nil and s.HitboxData == nil then out[#out + 1] = k end
            end
        end
        return out
    end
    local function selfShielded()
        local m = liveModel()
        return m ~= nil and shielded({ m = m })
