            sx, sz = sx + b.p.X, sz + b.p.Z
            if b.p.Y > top then top = b.p.Y end
        end
        local cx, cz = sx / #blds, sz / #blds
        return Vector3.new(cx, groundY(cx, cz, top) + ((Opt.k_bc_height and Opt.k_bc_height.Value) or 40), cz)
    end
    local function anyAlive(blds)
        for _, b in ipairs(blds) do if not destroyed(b.m) then return true end end
