        local look = tgt and Vector3.new(tgt.X, pos.Y, tgt.Z) or (pos + Vector3.new(rp.CFrame.LookVector.X, 0, rp.CFrame.LookVector.Z))
        if (look - pos).Magnitude < 0.5 then look = pos + Vector3.new(0, 0, -1) end
        rp.CFrame = CFrame.lookAt(pos, look)
        rp.AssemblyLinearVelocity = Vector3.zero
        rp.AssemblyAngularVelocity = Vector3.zero
