            if not on() then
                BC.hold = nil
                task.wait(0.3)
            elseif farming or pvpFarming or (Toggles.k_bossfarm and Toggles.k_bossfarm.Value) then
                task.wait(0.5)
            elseif not isSpawned() then
                BC.hold = nil
                status("respawning")
                if not respawning then ensureRespawn(island()) end
                task.wait(0.5)
            elseif archBusy then
                task.wait(0.3)
            else
                local blds = getBuildings()
                if #blds == 0 then
                    BC.hold = nil
                    status("no buildings loaded here (they rebuild after a while)")
                    task.wait(1)
                else
                    BC.t0 = BC.t0 or os.clock()
                    local hover = townHover(blds)
