                                    hit[b.m] = true
                                    BEAMCTL.pos = b.p
                                    pcall(function() BeamRemote:FireServer(b.p) end)
                                    task.wait((Opt.k_bc_step and Opt.k_bc_step.Value) or 0.12)
                                elseif i == #blds and not anyAlive(blds) then
                                    break
                                end
                            end
                            BEAMCTL.pos = nil
                            local killed = 0
                            for m in pairs(hit) do if destroyed(m) then killed = killed + 1 end end
                            BC.cycles = BC.cycles + 1
                            BC.killed = BC.killed + killed
                            status(("beam done (%d down), respawning"):format(killed))
                            BC.hold = nil
                            ensureRespawn(island())
                        end
                    end
                end
            end
        end
    end)
    onClean(function() BEAMCTL.pos = nil; BC.hold = nil end)
end)()

