do   -- movement (fly / fast walk / noclip) scoped so its ~19 locals don't count against the main chunk's 200-local limit
local flySpeed, walkSpeedVal = 120, 100
local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled
local flyConn, flyVel, flyUp, flyDown, flyHover, flyGui = nil, Vector3.zero, false, false, false, nil
local function makeFlyButtons()
    if flyGui then return end
    flyGui = Instance.new("ScreenGui")
    flyGui.Name = "CW_Fly"
    flyGui.ResetOnSpawn = false
    flyGui.IgnoreGuiInset = true
    flyGui.Parent = lp:WaitForChild("PlayerGui")
    local function mk(text, yoff)
        local b = Instance.new("TextButton")
        b.Size = UDim2.new(0, 72, 0, 72)
        b.AnchorPoint = Vector2.new(1, 1)
        b.Position = UDim2.new(1, -20, 1, yoff)
        b.BackgroundColor3 = Color3.fromRGB(25, 25, 25)
        b.BackgroundTransparency = 0.35
        b.TextColor3 = Color3.fromRGB(255, 255, 255)
        b.TextScaled = true
        b.Text = text
        b.Parent = flyGui
        return b
    end
    local up, down = mk("UP", -110), mk("DOWN", -28)
    local hover = mk("HOVER", -192)
    up.MouseButton1Down:Connect(function() flyUp = true end)
    up.MouseButton1Up:Connect(function() flyUp = false end)
    down.MouseButton1Down:Connect(function() flyDown = true end)
    down.MouseButton1Up:Connect(function() flyDown = false end)
    hover.MouseButton1Click:Connect(function()
        flyHover = not flyHover
        hover.BackgroundColor3 = flyHover and Color3.fromRGB(80, 140, 80) or Color3.fromRGB(25, 25, 25)
    end)
end
local function removeFlyButtons() if flyGui then flyGui:Destroy(); flyGui = nil end end
local function startFly()
    if flyConn then flyConn:Disconnect() end
    flyVel = Vector3.zero
    if isMobile then makeFlyButtons() end
    flyConn = track(RunService.RenderStepped:Connect(function(dt)
        local r, h = rootPart(), humanoid(); if not r then return end
        if h then h.PlatformStand = true end
        local c = liveModel()
        local sp = c and c:FindFirstChild("SwimmingPart")
        if sp then
            local bv = sp:FindFirstChild("SwimBv"); if bv then bv.MaxForce = Vector3.zero end
            local bg = sp:FindFirstChild("SwimBg"); if bg then bg.MaxTorque = Vector3.zero end
        end
        local cam = Workspace.CurrentCamera.CFrame
        local dir = Vector3.zero
        if isMobile then
            if not flyHover then dir += cam.LookVector end
            if flyUp then dir += Vector3.yAxis end
            if flyDown then dir -= Vector3.yAxis end
        else
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir += cam.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir -= cam.LookVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir -= cam.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir += cam.RightVector end
            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir += Vector3.yAxis end
            if UserInputService:IsKeyDown(Enum.KeyCode.Q) then dir -= Vector3.yAxis end
        end
        local target = (dir.Magnitude > 0) and dir.Unit * flySpeed or Vector3.zero
        flyVel = flyVel:Lerp(target, math.clamp(dt * 12, 0, 1))
        r.AssemblyLinearVelocity, r.AssemblyAngularVelocity = flyVel, Vector3.zero
    end))
end
local function stopFly()
    if flyConn then flyConn:Disconnect(); flyConn = nil end
    local h = humanoid(); if h then h.PlatformStand = false end
    local r = rootPart(); if r then r.AssemblyLinearVelocity = Vector3.zero end
    removeFlyButtons()
end
-- unload / re-execute: give the character back (fly leaves PlatformStand on; PvP can leave you underground
-- with collision off)
onClean(stopFly)
onClean(function()
    local r = rootPart()
