-- AUTO CLAIM (real decompiled source, 2026-10-01):
--   Quests     RS.Remotes.InvokeQuest:InvokeServer("GetQuests") -> {Daily={...}, Premium={...}}, each quest
--              {Id, Type, Goal, Progress, Completed, Claimed, Locked}; claim = InvokeServer("Claim", Type, Id).
--   Battlepass GetBattlepassData:InvokeServer() -> {Level, MaxLevel, ClaimedRewards={[n]=true}};
--              claim = ClaimBattlepassReward:InvokeServer(level). Server pushes QuestCompleted / BattlepassUpdated.
--   Codes      GameData.Code = { [code] = {Reward, Expire(unix)} }; used codes live in Data.<id>_Data.Redeem.
-- Own function scope so its locals don't count toward the main chunk's 200-local limit.
;(function()
    local AutoBox = CodesTab:AddLeftGroupbox("Auto Claim")
    AutoBox:AddToggle("k_auto_quests", { Text = "Auto Claim Quests", Default = false, Tooltip = "Claims every finished daily / premium quest (cells + battlepass XP)." })
    AutoBox:AddToggle("k_auto_bp", { Text = "Auto Claim Battlepass", Default = false, Tooltip = "Claims every battlepass tier you've unlocked." })
    AutoBox:AddToggle("k_auto_codes", { Text = "Auto Redeem New Codes", Default = true, Tooltip = "Redeems every active code you haven't used yet." })
    local lblQ = AutoBox:AddLabel("Quests: -", true)
    local lblBP = AutoBox:AddLabel("Battlepass: -", true)

    local InvokeQuest = Remotes:FindFirstChild("InvokeQuest")
    local QuestCompleted = Remotes:FindFirstChild("QuestCompleted")
    local GetBP = Remotes:FindFirstChild("GetBattlepassData")
    local ClaimBP = Remotes:FindFirstChild("ClaimBattlepassReward")
    local BPUpdated = Remotes:FindFirstChild("BattlepassUpdated")
    local function on(k) return Toggles[k] and Toggles[k].Value end
    local qBusy, bpBusy, cBusy = false, false, false

    local function claimQuests()
        if qBusy or not InvokeQuest or not on("k_auto_quests") then return end
        qBusy = true
        local ok, data = pcall(function() return InvokeQuest:InvokeServer("GetQuests") end)
        if ok and type(data) == "table" then
            local total, waiting, claimed = 0, 0, 0
            for _, tab in ipairs({ "Daily", "Premium" }) do
                for _, q in ipairs(type(data[tab]) == "table" and data[tab] or {}) do
                    if type(q) == "table" and q.Id then
                        total = total + 1
                        local done = q.Completed == true or (tonumber(q.Progress) or 0) >= (tonumber(q.Goal) or math.huge)
                        if done and q.Claimed ~= true and q.Locked ~= true and on("k_auto_quests") then
                            local okc, res = pcall(function() return InvokeQuest:InvokeServer("Claim", q.Type or tab, q.Id) end)
                            if okc and res then claimed = claimed + 1 end
                            task.wait(0.4)
                        elseif not done and q.Locked ~= true then
                            waiting = waiting + 1
                        end
                    end
                end
            end
            pcall(function() lblQ:SetText(("Quests: %d open  |  %d claimed just now"):format(waiting, claimed)) end)
            if claimed > 0 then notify(("Claimed %d quest%s"):format(claimed, claimed == 1 and "" or "s")) end
        else
            pcall(function() lblQ:SetText("Quests: not loaded yet, retrying") end)
        end
        qBusy = false
    end

    local function claimBP()
        if bpBusy or not (GetBP and ClaimBP) or not on("k_auto_bp") then return end
        bpBusy = true
        local ok, data = pcall(function() return GetBP:InvokeServer() end)
        if ok and type(data) == "table" then
            local lvl = math.floor(tonumber(data.Level) or 0)
            local maxL = math.floor(tonumber(data.MaxLevel) or 100)
            local got = {}
            for k, v in pairs(type(data.ClaimedRewards) == "table" and data.ClaimedRewards or {}) do
                local n = tonumber(k)
                if n and v then got[n] = true end
            end
            local claimed = 0
            for i = 1, math.min(lvl, maxL) do
                if not on("k_auto_bp") then break end
                if not got[i] then
                    local okc, res = pcall(function() return ClaimBP:InvokeServer(i) end)
                    if okc and res then claimed = claimed + 1 end
                    task.wait(0.4)
                end
            end
            pcall(function() lblBP:SetText(("Battlepass: level %d / %d  |  %d claimed just now"):format(lvl, maxL, claimed)) end)
            if claimed > 0 then notify(("Claimed %d battlepass reward%s"):format(claimed, claimed == 1 and "" or "s")) end
        else
            pcall(function() lblBP:SetText("Battlepass: not loaded yet, retrying") end)
        end
        bpBusy = false
    end

    local tried = {}
    local function autoCodes()
        if cBusy or not on("k_auto_codes") then return end
        local gd = gameData()
        if not (gd and type(gd.Code) == "table") then return end
        cBusy = true
        local used = {}
        local d = dataFolder()
        local r = d and d:FindFirstChild("Redeem")
        if r then
            for _, v in ipairs(r:GetChildren()) do
                if not v:IsA("BoolValue") or v.Value then used[v.Name:lower()] = true end
            end
        end
        local now = os.time()
        for code, info in pairs(gd.Code) do
            local exp = type(info) == "table" and tonumber(info.Expire) or nil
            if type(code) == "string" and not used[code:lower()] and not tried[code] and (not exp or exp > now) then
                tried[code] = true
                notify(code .. ": " .. redeemOne(code))
                task.wait(0.6)
            end
        end
        cBusy = false
    end

    if QuestCompleted then track(QuestCompleted.OnClientEvent:Connect(function() task.delay(1, claimQuests) end)) end
    if BPUpdated then track(BPUpdated.OnClientEvent:Connect(function() task.delay(1, claimBP) end)) end
    Toggles.k_auto_quests:OnChanged(function() if on("k_auto_quests") then task.spawn(claimQuests) end end)
    Toggles.k_auto_bp:OnChanged(function() if on("k_auto_bp") then task.spawn(claimBP) end end)
    Toggles.k_auto_codes:OnChanged(function() if on("k_auto_codes") then task.spawn(autoCodes) end end)
    task.spawn(function()
        task.wait(8)   -- let the game load its quest / battlepass data first
        local n = 0
        while RUNNING do
            pcall(claimQuests)
            pcall(claimBP)
            if n % 5 == 0 then pcall(autoCodes) end
            n = n + 1
            task.wait(60)
        end
    end)
end)()

