local function httpGet(url)
    local req = (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request) or http_request or request
    if req then
        local ok, res = pcall(req, { Url = url, Method = "GET" })
        if ok and type(res) == "table" and res.Body then return res.Body end
    end
    local ok, res = pcall(function() return game:HttpGet(url) end)
    if ok then return res end
    return nil
end
local hopping = false
-- Pull joinable servers across pages. keep(server)->bool filters; returns { {id=,playing=}, ... }.
local function collectServers(passes, keep)
    local placeId = game.PlaceId
    local out, cursor = {}, ""
    for _ = 1, passes do
        local url = ("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100"):format(placeId)
        if cursor ~= "" then url = url .. "&cursor=" .. cursor end
        local body = httpGet(url)
        if not body then break end
        local ok, data = pcall(function() return HttpService:JSONDecode(body) end)
        if not ok or type(data) ~= "table" then break end
        for _, s in ipairs(data.data or {}) do
            if type(s.playing) == "number" and s.id ~= game.JobId and s.playing < (s.maxPlayers or 999) and keep(s) then
                out[#out + 1] = { id = s.id, playing = s.playing }
            end
        end
        if data.nextPageCursor and data.nextPageCursor ~= "" then cursor = data.nextPageCursor else break end
        task.wait(0.15)
    end
    return out
end
-- Teleport through candidate JobIds in order, advancing to the next if one fails (stale/full instance).
-- This is the fix for "it doesn't join anymore": a single silent TeleportToPlaceInstance failure no
-- longer strands you -- we retry the next-best server.
local function tryTeleportList(list, cap)
    local placeId = game.PlaceId
    for i = 1, math.min(#list, cap or 6) do
        local failed = false
        local conn = TeleportService.TeleportInitFailed:Connect(function() failed = true end)
        local ok = pcall(function() TeleportService:TeleportToPlaceInstance(placeId, list[i].id, lp) end)
        if ok then
            local t0 = os.clock()
            repeat task.wait(0.25) until failed or os.clock() - t0 > 5
        end
        conn:Disconnect()
        if ok and not failed then return true end   -- teleport accepted / in progress
    end
    return false
end

local function joinLowest()
    if hopping then return end
    hopping = true
    -- Asc already returns the emptiest servers on the first pages, so few passes is plenty AND avoids
    -- the Roblox API rate-limit (hammering 12 pages was causing "no server found" = 429 throttle).
    local list = collectServers(5, function() return true end)
    if #list == 0 then task.wait(1.5); list = collectServers(5, function() return true end) end   -- retry once if throttled
    table.sort(list, function(a, b) return a.playing < b.playing end)
    hopping = false
    if #list == 0 then notify("No server found (Roblox server list busy) - wait ~30s and retry"); return end
    notify("Joining emptiest server (" .. list[1].playing .. " players)")
    if not tryTeleportList(list, 8) then notify("Empty servers were full/stale, try again") end
end

-- PvP hop: jump to a DIFFERENT populated server to farm (not the emptiest).
-- Also used by the boss auto-hop with a higher player floor (the boss portal needs 3 players).
pvpHop = function(minPlayers, tag)
    if hopping then return end
    hopping = true
    minPlayers, tag = minPlayers or 2, tag or "PvP hop"
    local pool = collectServers(8, function(s) return s.playing >= minPlayers end)
    hopping = false
    if #pool == 0 then notify(tag .. ": no populated server found"); return end
    for i = #pool, 2, -1 do local j = math.random(i); pool[i], pool[j] = pool[j], pool[i] end   -- shuffle
    notify(tag .. " -> new server (" .. #pool .. " options)")
    tryTeleportList(pool, 6)
end

-- Join a specific server by its JobId (paste it in).
local function joinJob(jobId)
    jobId = tostring(jobId or ""):gsub("^%s*(.-)%s*$", "%1")
    if jobId == "" then notify("Paste a JobId first"); return end
    if jobId == game.JobId then notify("That's the server you're already in"); return end
    notify("Teleporting to that server...")
    if not tryTeleportList({ { id = jobId } }, 1) then notify("Join failed (bad/full JobId)") end
end

-- Find and join a server whose player count is within [minP, maxP].
local function joinByCount(minP, maxP)
    if hopping then return end
    hopping = true
    local matches = collectServers(15, function(s) return s.playing >= minP and s.playing <= maxP end)
    hopping = false
    if #matches == 0 then notify(("No server with %d-%d players found"):format(minP, maxP)); return end
    for i = #matches, 2, -1 do local j = math.random(i); matches[i], matches[j] = matches[j], matches[i] end
    notify(("Joining a %d-%d player server (%d found)"):format(minP, maxP, #matches))
    if not tryTeleportList(matches, 6) then notify("Matching servers were full/stale, try again") end
end

-- AUTO SKIP: the "Loading Assets..." screen has a real SKIP button (capture-confirmed). It's created
-- during load (not a persistent PlayerGui child), so we deep-watch PlayerGui and fire the SKIP button
-- the instant it appears. Also fires again on every server hop, since each new server reloads assets.
-- For it to catch a join the script must auto-execute on join (autoload).
local trySkip, setAutoSkip
do
    local fireSig = firesignal or (syn and syn.firesignal) or (getgenv and getgenv().firesignal)
    local getCons2 = getconnections or (syn and syn.getconnections) or (getgenv and getgenv().getconnections)
    local function clickButton(btn)
        local fired = false
        if getCons2 then
            -- real loading script listens on MouseButton1Click; fire ONE signal (firing all three re-ran
            -- toggle-style handlers 2-3x and could cancel themselves out)
            for _, sig in ipairs({ btn.MouseButton1Click, btn.Activated }) do
                local ok, cons = pcall(getCons2, sig)
                if ok and cons and #cons > 0 then
                    for _, c in ipairs(cons) do pcall(function() c:Fire() end) end
                    fired = true
                    break
                end
            end
        end
        if not fired and fireSig then pcall(fireSig, btn.MouseButton1Click) end
    end
    local function isSkipButton(d)
        if not (d:IsA("TextButton") or d:IsA("ImageButton")) then return false end
        -- only the loading screen (real source: PlayerGui.Loading.Screen.SkipButton). Without this it would
        -- click any "skip" button the game adds later (battlepass / quest / cutscene UIs).
        local sg = d:FindFirstAncestorWhichIsA("ScreenGui")
        if not (sg and sg.Name:lower():find("load")) then return false end
        if d.Name:lower():find("skip") then return true end
        if d:IsA("TextButton") then                        -- ImageButton has no .Text (reading it errors)
            local t = tostring(d.Text or ""):upper():gsub("%s", "")
            if t == "SKIP" then return true end
        end
        -- a button whose visible label is a child TextLabel/TextButton reading "SKIP"
        for _, c in ipairs(d:GetChildren()) do
            if (c:IsA("TextLabel") or c:IsA("TextButton")) and tostring(c.Text or ""):upper():gsub("%s", "") == "SKIP" then
                return true
            end
        end
        return false
    end
    function trySkip()
        local pg = lp:FindFirstChild("PlayerGui")
        if not pg then return false end
        local hit = false
        for _, d in ipairs(pg:GetDescendants()) do
            if isSkipButton(d) then clickButton(d); hit = true end
        end
        return hit
    end
    local skipConn
    function setAutoSkip(on)
        if skipConn then skipConn:Disconnect(); skipConn = nil end
        if not on then return end
        pcall(function() game:GetService("ReplicatedFirst"):RemoveDefaultLoadingScreen() end)
        trySkip()
        local pg = lp:FindFirstChild("PlayerGui")
        if pg then
            skipConn = track(pg.DescendantAdded:Connect(function(d)
                if not (Toggles.k_autoskip and Toggles.k_autoskip.Value) then return end
                -- the SkipButton, or the whole "Loading" ScreenGui, can arrive as one subtree -> rescan
                if isSkipButton(d) or (d:IsA("ScreenGui") and d.Name:lower():find("load")) then
                    task.wait()
                    trySkip()
                end
            end))
        end
    end
end

