-- VOTE KICK: VoteRemote:FireServer("StartVote", name) opens a kick vote; ("Vote", name, true/false)
-- casts. Incoming votes arrive as OnClientEvent("NewVote", targetName, starterId, cooldown, needed).
-- Scoped in a do-block to keep its locals off the main chunk's 200-local budget.
do
    local VoteRemote = Remotes:FindFirstChild("VoteRemote")
    local VoteBox = SettingsTab:AddRightGroupbox("Vote Kick")
    VoteBox:AddDropdown("k_vote_target", { Values = {}, Default = "", AllowNull = true, Text = "Player" })
    STK.track("k_vote_target")
    VoteBox:AddButton({ Text = "Start Vote Kick", Func = function()
        local name = Opt.k_vote_target and Opt.k_vote_target.Value
        if not name or name == "" then notify("Pick a player"); return end
        if not VoteRemote then notify("No vote remote"); return end
        pcall(function() VoteRemote:FireServer("StartVote", name) end)
        task.wait(0.3)
        pcall(function() VoteRemote:FireServer("Vote", name, true) end)   -- cast your own yes on it
        notify("Vote kick started on " .. name)
    end })
    VoteBox:AddToggle("k_vote_target_auto", { Text = "Keep Voting Target", Default = false, Tooltip = "Repeatedly opens a kick vote on the selected player whenever no vote is active (respects the game's cooldown)." })
    VoteBox:AddDropdown("k_vote_exclude", { Values = {}, Default = {}, Multi = true, AllowNull = true, Text = "Exclude (never kick)", Tooltip = "Players here are protected: Kick Everyone won't vote them, and Auto-Agree won't vote yes on a kick against them." })
    STK.track("k_vote_exclude")
    VoteBox:AddToggle("k_vote_all", { Text = "Kick Everyone (except excluded)", Default = false, Tooltip = "Cycles a kick vote against every player NOT in the Exclude list, one at a time (respects the game's cooldown)." })
    VoteBox:AddToggle("k_vote_auto", { Text = "Auto-Agree All Kicks", Default = false, Tooltip = "Auto-votes YES on every kick vote that starts (skips anyone in the Exclude list)." })
    -- lowercased set of protected players
    local function excludeSet()
        local dd = Opt.k_vote_exclude; local v = dd and dd.Value
        if type(v) ~= "table" then return nil end
        local set, any = {}, false
        for k, val in pairs(v) do
            if val == true then set[k:lower()] = true; any = true
            elseif type(val) == "string" then set[val:lower()] = true; any = true end
        end
        return any and set or nil
    end
    if VoteRemote then
        track(VoteRemote.OnClientEvent:Connect(function(action, target)
            if action == "NewVote" and type(target) == "string" and target ~= lp.Name   -- never vote to kick yourself
                and Toggles.k_vote_auto and Toggles.k_vote_auto.Value then
                local ex = excludeSet()
                if not (ex and ex[target:lower()]) then   -- don't vote yes on a protected player
                    task.wait(0.2)
                    pcall(function() VoteRemote:FireServer("Vote", target, true) end)
                end
            end
        end))
        local allIdx = 0
        task.spawn(function()
            while RUNNING do
                if Toggles.k_vote_all and Toggles.k_vote_all.Value then
                    local ex = excludeSet()
                    local targets = {}
                    for _, p in ipairs(Players:GetPlayers()) do
                        if p ~= lp and not (ex and ex[p.Name:lower()]) then targets[#targets + 1] = p.Name end
                    end
                    if #targets > 0 then
                        allIdx = allIdx % #targets + 1   -- rotate one target per cycle
                        local name = targets[allIdx]
                        pcall(function() VoteRemote:FireServer("StartVote", name) end)
                        task.wait(0.3)
                        pcall(function() VoteRemote:FireServer("Vote", name, true) end)
                    end
                    task.wait(15)
                elseif Toggles.k_vote_target_auto and Toggles.k_vote_target_auto.Value then
                    local name = Opt.k_vote_target and Opt.k_vote_target.Value
                    if name and name ~= "" and Players:FindFirstChild(name) then
                        pcall(function() VoteRemote:FireServer("StartVote", name) end)
                        task.wait(0.3)
                        pcall(function() VoteRemote:FireServer("Vote", name, true) end)
                    end
                    task.wait(15)
                else
                    task.wait(1)
                end
            end
        end)
    end
    task.spawn(function()
        local last = ""
        while RUNNING do
            local names = {}
            for _, p in ipairs(Players:GetPlayers()) do if p ~= lp then names[#names + 1] = p.Name end end
            table.sort(names)
            local sig = table.concat(names, "|")
            if sig ~= last then
                last = sig
                STK.setValues("k_vote_target", names)
                STK.setValues("k_vote_exclude", names)
            end
            task.wait(2)
        end
    end)
end

